"use client";
/* eslint-disable @typescript-eslint/no-explicit-any */

import { useEffect, useMemo, useState, type ComponentType } from "react";
import {
  AreaChart, Area, BarChart as ReBarChart, Bar, CartesianGrid, Cell, Pie, PieChart,
  ResponsiveContainer, Tooltip, XAxis, YAxis,
} from "recharts";
import {
  ArrowDownLeft, ArrowRight, ArrowUpRight, Bell, CalendarDays, Check,
  ChevronDown, ChevronRight, CircleDollarSign, CreditCard, Download, Eye,
  EyeOff, Flag, Heart, Home, Landmark, LayoutDashboard, Lightbulb, Menu,
  MessageCircleHeart, Moon, MoreHorizontal, Plus, ReceiptText, Search,
  Percent, Settings, Sparkles, Sun, Target, TrendingDown, TrendingUp, Users, WalletCards,
  X, Zap,
} from "lucide-react";
import { AuthGate } from "@/components/auth-gate";
import { CloudSync } from "@/components/cloud-sync";
import { useAuth } from "@/lib/auth-context";
import { createClient as createBrowserClient } from "@/lib/supabase/client";

const brl = (value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value);
const DEFAULT_TRANSACTION_CATEGORIES = ['Salário','Alimentação','Mercado','Restaurante','Delivery','Transporte','Combustível','Aluguel','Condomínio','Internet','Luz','Água','Telefone','Saúde','Educação','Filhos','Viagens','Lazer','Compras','Assinaturas','Investimentos','Dívidas','Seguros','Impostos','Outros'];
const appAction = (detail: string | { page: string }) => window.dispatchEvent(new CustomEvent('juntos-action', { detail }));
const systemDialog=(message:string,options:{title?:string;confirmLabel?:string;cancelLabel?:string;danger?:boolean;alert?:boolean}={})=>new Promise<boolean>(resolve=>window.dispatchEvent(new CustomEvent('juntos-dialog',{detail:{message,...options,resolve}})));
const confirmDialog=(message:string,title='Confirmar ação')=>systemDialog(message,{title,confirmLabel:'Confirmar',cancelLabel:'Cancelar',danger:/excluir|apagar|restaurar/i.test(message)});
const alertDialog=(message:string,title='Aviso')=>systemDialog(message,{title,confirmLabel:'Entendi',alert:true});
const displayPerson=(people:any,key:string)=>key==='Rafael'?people.Rafael.name.split(' ')[0]:key==='Mariana'?people.Mariana.name.split(' ')[0]:key;
const displayTitle=(people:any,title:string)=>title==='Salário Rafael'?'Salário '+people.Rafael.name.split(' ')[0]:title;

const menu = [
  ["Dashboard", LayoutDashboard], ["Transações", ReceiptText], ["Orçamentos", CircleDollarSign],
  ["Cartões", CreditCard], ["Calendário", CalendarDays], ["Metas", Target], ["Dívidas", Landmark],
  ["Assinaturas", Zap], ["App de compras", Search],
  ["Relatórios", TrendingUp], ["IA Conselheira", MessageCircleHeart],
] as const;

const transactions: any[] = [];


const expenses: any[] = [];
const cashflow: any[] = [];

function Avatar({ who, small = false, label }: { who: "R" | "M"; small?: boolean; label?: string }) {
  return <div className={`avatar ${small ? "small" : ""} ${who === "M" ? "mariana" : "rafael"}`}>{(label||who).trim().charAt(0).toUpperCase()}</div>;
}

function Logo() {
  return <div className="logo"><span><Heart size={17} fill="currentColor" /></span><div>Juntos <b>Finance</b></div></div>;
}

function MetricCard({ label, value, detail, icon: Icon, tone = "default", hide = false }: { label: string; value: string; detail?: string; icon: ComponentType<{size?: number}>; tone?: string; hide?: boolean }) {
  return <article className={`metric card ${tone}`}>
    <div className="metric-head"><span>{label}</span><i><Icon size={18} /></i></div>
    <strong>{hide ? "••••••" : value}</strong>
    {detail&&<small>{detail}</small>}
  </article>;
}

function Dashboard({ onNew, onAi, hidden, people, currentName }: { onNew: () => void; onAi: () => void; hidden: boolean; people:any; currentName?:string }) {
  const [period,setPeriod]=useState(()=>new Intl.DateTimeFormat('en-CA').format(new Date()).slice(0,7));
  const [dashboardItems,setDashboardItems]=useState<any[]>([]);
  const [dashboardGoals,setDashboardGoals]=useState<any[]>([]);
  const [calendarEvents,setCalendarEvents]=useState<any[]>([]);
  const [customizing,setCustomizing]=useState(false);
  const [dashboardPrefs,setDashboardPrefs]=useState({metrics:true,insights:true,charts:true,activity:true,goals:true});
  const todayLabel=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(new Date()).replace(/^./,letter=>letter.toUpperCase());
  useEffect(()=>{const loadTransactions=()=>{const saved=localStorage.getItem('juntos-transactions');setDashboardItems(saved?JSON.parse(saved):transactions)};loadTransactions();window.addEventListener('juntos-transactions-updated',loadTransactions);return()=>window.removeEventListener('juntos-transactions-updated',loadTransactions)},[]);
  useEffect(()=>{const loadGoals=()=>{try{setDashboardGoals(JSON.parse(localStorage.getItem('juntos-goals')||'[]'))}catch{setDashboardGoals([])}};loadGoals();window.addEventListener('juntos-goals-updated',loadGoals);return()=>window.removeEventListener('juntos-goals-updated',loadGoals)},[]);
  useEffect(()=>{const load=()=>{try{setCalendarEvents(JSON.parse(localStorage.getItem('juntos-calendar-events')||'[]'));const saved=JSON.parse(localStorage.getItem('juntos-dashboard-prefs')||'null');if(saved)setDashboardPrefs(previous=>({...previous,...saved}))}catch{}};load();window.addEventListener('juntos-calendar-updated',load);window.addEventListener('juntos-cloud-synced',load);return()=>{window.removeEventListener('juntos-calendar-updated',load);window.removeEventListener('juntos-cloud-synced',load)}},[]);
  const toggleWidget=(key:keyof typeof dashboardPrefs)=>setDashboardPrefs(previous=>{const next={...previous,[key]:!previous[key]};localStorage.setItem('juntos-dashboard-prefs',JSON.stringify(next));return next});
  const periodItems=dashboardItems.filter(item=>!item.dateInput||item.dateInput.startsWith(period));
  const monthIncome=periodItems.filter(item=>item.type==='in').reduce((total,item)=>total+Number(item.value||0),0);
  const monthExpense=periodItems.filter(item=>item.type==='out').reduce((total,item)=>total+Number(item.value||0),0);
  const monthSavings=monthIncome-monthExpense;
  const [selectedYear,selectedMonth]=period.split('-').map(Number);const previousDate=new Date(selectedYear,selectedMonth-2,1);const previousKey=previousDate.getFullYear()+'-'+String(previousDate.getMonth()+1).padStart(2,'0');const previousItems=dashboardItems.filter(item=>item.dateInput?.startsWith(previousKey));const previousResult=previousItems.filter(item=>item.type==='in').reduce((sum,item)=>sum+Number(item.value||0),0)-previousItems.filter(item=>item.type==='out').reduce((sum,item)=>sum+Number(item.value||0),0);const comparison=previousResult===0?(monthSavings===0?0:100):Math.round((monthSavings-previousResult)/Math.abs(previousResult)*100);
  const today=new Intl.DateTimeFormat('en-CA').format(new Date());const futureLimitDate=new Date();futureLimitDate.setDate(futureLimitDate.getDate()+30);const futureLimit=new Intl.DateTimeFormat('en-CA').format(futureLimitDate);const futureTransactions=dashboardItems.filter(item=>item.dateInput>today&&item.dateInput<=futureLimit);const projectedBalance=monthSavings+futureTransactions.reduce((sum,item)=>sum+(item.type==='in'?Number(item.value||0):-Number(item.value||0)),0);const upcomingPayments=[...dashboardItems.filter(item=>item.type==='out'&&item.dateInput>=today),...calendarEvents.filter(item=>item.type!=='income'&&item.date>=today).map(item=>({...item,dateInput:item.date,category:'Calendário'}))].sort((a,b)=>(a.dateInput||'').localeCompare(b.dateInput||'')).slice(0,3);
  const chartColors=['#7f2854','#b76a8e','#d79ab6','#8f6bb2','#d39155','#4c8d7b','#6d7f9f'];
  const categoryTotals=Object.entries(periodItems.filter(item=>item.type==='out').reduce((groups:Record<string,number>,item:any)=>{groups[item.category||'Outros']=(groups[item.category||'Outros']||0)+Number(item.value||0);return groups},{})).sort((a,b)=>b[1]-a[1]);
  const categoryExpenses=categoryTotals.map(([name,value],index)=>({name,value,percentage:monthExpense?Math.round(value/monthExpense*100):0,color:chartColors[index%chartColors.length]}));
  const dashboardCashflow=Array.from({length:6},(_,offset)=>{const [year,month]=period.split('-').map(Number);const date=new Date(year,month-1-(5-offset),1);const key=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0');const items=dashboardItems.filter(item=>item.dateInput?.startsWith(key));return {m:new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(date).replace('.',''),receita:items.filter(item=>item.type==='in').reduce((sum,item)=>sum+Number(item.value||0),0),despesa:items.filter(item=>item.type==='out').reduce((sum,item)=>sum+Number(item.value||0),0)}});
  const periodOptions=Array.from({length:36},(_,i)=>{const date=new Date(2025+Math.floor(i/12),i%12,1);return {value:date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0'),label:new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(date).replace(/^./,x=>x.toUpperCase())}});
  return <>
    <section className="welcome">
      <div><p>{todayLabel}</p><h1>Olá, {(currentName||people.Rafael.name).trim().split(' ')[0]} <span>👋</span></h1><small>Seu dinheiro, seus planos, uma vida juntos.</small></div>
      <div className="welcome-actions">
        <label className="ghost period period-picker"><CalendarDays size={17}/><span>{periodOptions.find(x=>x.value===period)?.label}</span><ChevronDown size={16}/><select value={period} onChange={e=>setPeriod(e.target.value)} aria-label="Selecionar mês e ano">{periodOptions.map(x=><option value={x.value} key={x.value}>{x.label}</option>)}</select></label>
        <button className="ghost" onClick={()=>setCustomizing(!customizing)}><Settings size={17}/> Personalizar</button><button className="primary" onClick={onNew}><Plus size={18} /> Nova transação</button>
      </div>
    </section>

    {customizing&&<section className="card dashboard-customizer"><div><b>Personalizar Dashboard</b><small>Escolha os painéis que deseja visualizar.</small></div>{Object.entries({metrics:'Resumo financeiro',insights:'Comparação e projeção',charts:'Gráficos',activity:'Movimentações e alertas',goals:'Metas'}).map(([key,label])=><button className={`toggle-option ${dashboardPrefs[key as keyof typeof dashboardPrefs]?'active':''}`} onClick={()=>toggleWidget(key as keyof typeof dashboardPrefs)} key={key}><Check size={15}/>{label}</button>)}</section>}
    <div className="metrics-grid" style={{display:dashboardPrefs.metrics?'grid':'none'}}>
      <MetricCard label="Saldo em contas" value={brl(Math.max(0,monthSavings))} detail="Contas e PIX" icon={WalletCards} tone="balance" hide={hidden}/>
      <MetricCard label={`Receitas (${period})`} value={`+ ${brl(monthIncome)}`} detail="Salários e entradas" icon={ArrowUpRight} tone="positive" hide={hidden}/>
      <MetricCard label={`Despesas (${period})`} value={`- ${brl(monthExpense)}`} detail="Gastos registrados" icon={ArrowDownLeft} tone="negative" hide={hidden}/>
      <MetricCard label="Economia líquida" value={`${monthIncome>0?Math.max(0,Math.round(monthSavings/monthIncome*100)):0}%`} icon={Percent} tone="purple" hide={hidden}/>
    </div>

    <div className="metrics-grid compact dashboard-insights" style={{display:dashboardPrefs.insights?'grid':'none'}}><MetricCard label="Comparação mensal" value={`${comparison>=0?'+':''}${comparison}%`} detail={`Resultado anterior: ${brl(previousResult)}`} icon={comparison>=0?TrendingUp:TrendingDown} tone={comparison>=0?'positive':'negative'}/><MetricCard label="Saldo projetado em 30 dias" value={brl(projectedBalance)} detail={`${futureTransactions.length} lançamentos futuros`} icon={TrendingUp} tone="purple"/></div>
    <div className="content-grid charts-row" style={{display:dashboardPrefs.charts?'grid':'none'}}>
      <section className="card chart-card wide cashflow-bars">
        <div className="section-title"><div><h3>Receitas vs Despesas</h3></div></div>
        <div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><ReBarChart data={dashboardCashflow} margin={{top:12,right:8,left:8,bottom:0}} barGap={5} barCategoryGap="16%"><CartesianGrid vertical={false} stroke="#eee7eb"/><XAxis dataKey="m" axisLine={false} tickLine={false} tick={{fill:'#6f686c',fontSize:11}}/><YAxis hide/><Tooltip cursor={{fill:'rgba(112,34,68,.04)'}} itemSorter={(item)=>item.dataKey === 'receita' ? -1 : 1} formatter={(v,name)=>[brl(Number(v)),String(name)]}/><Bar dataKey="receita" name="Receita" fill="#2f9961" radius={[6,6,0,0]} maxBarSize={72}/><Bar dataKey="despesa" name="Despesa" fill="#8b263f" radius={[6,6,0,0]} maxBarSize={72}/></ReBarChart></ResponsiveContainer></div>
        <div className="legend bar-legend"><span><i className="income-bar"/>Receita</span><span><i className="expense-bar"/>Despesa</span></div>
      </section>
      <section className="card chart-card donut-card">
        <div className="section-title"><div><h3>Gastos por categoria</h3><p>{periodOptions.find(option=>option.value===period)?.label}</p></div><button className="icon-button" onClick={()=>appAction({page:'Transações'})} aria-label="Ver gastos por categoria"><MoreHorizontal size={19}/></button></div>
        <div className="donut-wrap"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={categoryExpenses} dataKey="value" innerRadius={54} outerRadius={78} paddingAngle={3} startAngle={90} endAngle={-270}>{categoryExpenses.map((x)=><Cell key={x.name} fill={x.color}/>)}</Pie><Tooltip formatter={(value)=>brl(Number(value))}/></PieChart></ResponsiveContainer><div className="donut-label"><b>{brl(monthExpense)}</b><small>Total gasto</small></div></div>
        <div className="expense-legend">{categoryExpenses.map(x=><div key={x.name}><span><i style={{background:x.color}}/>{x.name}</span><b>{x.percentage}%</b></div>)}</div>
      </section>
    </div>

    <div className="content-grid lower-row" style={{display:dashboardPrefs.activity?'grid':'none'}}>
      <section className="card transactions-card">
        <div className="section-title"><div><h3>Movimentações recentes</h3><p>Suas últimas transações</p></div><button className="text-button" onClick={()=>appAction({page:'Transações'})}>Ver todas <ArrowRight size={15}/></button></div>
        <div className="transaction-list">{periodItems.length?periodItems.slice(0,5).map(t=><div className="transaction" key={t.id}><div className={`transaction-icon ${t.type}`}>{t.icon}</div><div className="transaction-name"><b>{displayTitle(people,t.title)}</b><span>{t.category} · {displayPerson(people,t.person)}</span></div><div className="transaction-date">{t.date}</div><strong className={t.type}>{t.type === "in" ? "+" : "−"} {brl(t.value)}</strong></div>):<div className="organizer-empty">Nenhuma transação cadastrada.</div>}</div>
      </section>
      <aside className="side-stack">
        <section className="card ai-alerts-card"><div className="ai-alerts-head"><div><h3>Alertas da IA <span>0</span></h3><button onClick={onAi}>IA Conselheira <ChevronRight size={14}/></button></div></div><div className="ai-alert-list"><article><i className="alert-green"><Lightbulb size={18}/></i><div><b>Nenhum alerta por enquanto</b><p>Cadastre transações, contas e metas para receber análises.</p></div></article></div></section>
        <section className="card upcoming"><div className="section-title"><div><h3>Próximos pagamentos</h3><p>{upcomingPayments.length?upcomingPayments.length+' compromissos encontrados':'Nenhum compromisso cadastrado'}</p></div></div>{upcomingPayments.length?upcomingPayments.map(item=><button className="agenda-date" onClick={()=>appAction({page:'Calendário'})} key={(item.id||item.title)+'-'+item.dateInput}><b>{item.dateInput?.slice(-2)}</b><span>{item.title}<small>{item.category||'Vencimento'}</small></span><strong>{item.value?brl(Number(item.value)):'—'}</strong></button>):<p className="agenda-empty">Adicione eventos no calendário para acompanhar vencimentos.</p>}</section>
      </aside>
    </div>

    <section className="goals-section" style={{display:dashboardPrefs.goals?'block':'none'}}><div className="section-title"><div><h3>Minhas metas</h3><p>Transformando planos em conquistas</p></div><button className="text-button" onClick={()=>appAction({page:"Metas"})}>Ver todas <ArrowRight size={15}/></button></div><div className="goals-grid">{dashboardGoals.length?dashboardGoals.map(g=>{const pct=Math.round(g.current/g.total*100);return <article className="card goal" key={g.title}><div className="goal-top"><i>{g.emoji}</i><span><b>{g.title}</b><small>Meta para {g.date}</small></span><strong>{pct}%</strong></div><div className="progress"><span style={{width:`${pct}%`,background:g.color}}/></div><div className="goal-values"><b>{hidden ? "••••" : brl(g.current)}</b><span>de {hidden ? "••••" : brl(g.total)}</span></div></article>}):<div className="organizer-empty">Nenhuma meta cadastrada.</div>}</div></section>

  </>;
}

function TransactionsPage({ onNew, people, isCouple }: { onNew: () => void; people:any; isCouple:boolean }) {
  const [query,setQuery]=useState(''); const [person,setPerson]=useState('Todas'); const [period,setPeriod]=useState(()=>new Intl.DateTimeFormat('en-CA').format(new Date()).slice(0,7)); const [openMenu,setOpenMenu]=useState<number|null>(null); const [editing,setEditing]=useState<any|null>(null); const [editForm,setEditForm]=useState<any>({});
  const [items,setItems]=useState<any[]>(transactions);
  const [categories,setCategories]=useState<string[]>(DEFAULT_TRANSACTION_CATEGORIES);
  useEffect(()=>{const load=()=>{const saved=localStorage.getItem('juntos-transactions');setItems(saved?JSON.parse(saved):transactions);try{const configured=JSON.parse(localStorage.getItem('juntos-settings')||'{}').categories;if(Array.isArray(configured))setCategories([...new Set([...DEFAULT_TRANSACTION_CATEGORIES,...configured])])}catch{}};load();window.addEventListener('juntos-transactions-updated',load);window.addEventListener('juntos-cloud-synced',load);return()=>{window.removeEventListener('juntos-transactions-updated',load);window.removeEventListener('juntos-cloud-synced',load)}},[]);
  const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-transactions',JSON.stringify(next));window.dispatchEvent(new Event('juntos-transactions-updated'))};
  const openEdit=(t:any)=>{setEditing(t);setEditForm({...t,value:String(t.value).replace('.',','),dateInput:t.dateInput||(t.date?.includes('-')?t.date:period+'-'+String(t.date).replace(/\D/g,'').padStart(2,'0'))});setOpenMenu(null)};
  const saveEdit=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(editForm.value).replace(/[.]/g,'').replace(',','.'));if(!editForm.title?.trim()||Number.isNaN(value))return;persist(items.map(x=>x.id===editing.id?{...x,...editForm,title:editForm.title.trim(),value,date:editForm.dateInput?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(editForm.dateInput+'T12:00:00')).replace('.',''):x.date}:x));setEditing(null);appAction('Transação atualizada com sucesso.')};
  const remove=async(t:any)=>{if(await confirmDialog(`Excluir “${t.title}”?`)){persist(items.filter(x=>x.id!==t.id));setOpenMenu(null);appAction('Transação excluída.')}};
  const periodItems=items.filter(t=>!t.dateInput||t.dateInput.startsWith(period));
  const filtered=periodItems.filter(t=>(t.title.toLowerCase().includes(query.toLowerCase())||t.category.toLowerCase().includes(query.toLowerCase()))&&(person==='Todas'||t.person===person));
  const income=periodItems.filter(t=>t.type==='in').reduce((sum,t)=>sum+Number(t.value),0); const expense=periodItems.filter(t=>t.type==='out').reduce((sum,t)=>sum+Number(t.value),0); const result=income-expense;
  return <div className="page-stack"><div className="page-heading"><div><p>Controle financeiro</p><h1>Transações</h1><span>Acompanhe tudo que entra e sai.</span></div><button className="primary" onClick={onNew}><Plus size={18}/> Nova transação</button></div><div className="metrics-grid compact"><MetricCard label="Entradas" value={brl(income)} detail="Este mês" icon={TrendingUp} tone="positive"/><MetricCard label="Saídas" value={brl(expense)} detail="Este mês" icon={TrendingDown} tone="negative"/><MetricCard label="Resultado" value={brl(result)} detail={result>=0?'Positivo':'Negativo'} icon={WalletCards} tone="purple"/></div><section className="card table-card"><div className="toolbar"><label className="search"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar transação..."/></label><select className="ghost toolbar-select" value={person} onChange={e=>setPerson(e.target.value)}><option>Todas</option><option value="Rafael">Você</option><option value="Mariana">Parceiro(a)</option><option>Casal</option></select><input className="ghost toolbar-month" type="month" value={period} onChange={e=>setPeriod(e.target.value)}/></div><div className="transaction-list large">{filtered.map(t=><div className="transaction" key={t.id}><div className={`transaction-icon ${t.type}`}>{t.icon}</div><div className="transaction-name"><b>{displayTitle(people,t.title)}</b><span>{t.category}</span><small className="transaction-mobile-date">{t.date}</small></div><span className="person-pill">{displayPerson(people,t.person)}</span><div className="transaction-date">{t.date}</div><strong className={t.type}>{t.type === 'in' ? '+' : '−'} {brl(t.value)}</strong><div className="row-actions"><button className="icon-button" onClick={()=>setOpenMenu(openMenu===t.id?null:t.id)} aria-label="Opções da transação"><MoreHorizontal size={17}/></button>{openMenu===t.id&&<div className="row-menu"><button onClick={()=>openEdit(t)}>Editar</button><button className="danger" onClick={()=>remove(t)}>Excluir</button></div>}</div></div>)}</div></section>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal edit-transaction-modal" onSubmit={saveEdit}><div className="edit-modal-head"><div><span>EDITAR MOVIMENTAÇÃO</span><h2>Editar transação</h2><p>Atualize os dados do lançamento selecionado.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X size={19}/></button></div><div className="type-switch edit-types"><button type="button" className={editForm.type==='in'?'active':''} onClick={()=>setEditForm({...editForm,type:'in',icon:'↗'})}>Receita</button><button type="button" className={editForm.type==='out'?'active':''} onClick={()=>setEditForm({...editForm,type:'out',icon:'−'})}>Despesa</button></div><div className="edit-form-grid"><label className="field-full">Descrição<input value={editForm.title||''} onChange={e=>setEditForm({...editForm,title:e.target.value})} required/></label><label>Valor (R$)<input value={editForm.value||''} onChange={e=>setEditForm({...editForm,value:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal" required/></label><label>Data<input type="date" value={editForm.dateInput||''} onChange={e=>setEditForm({...editForm,dateInput:e.target.value})}/></label><label>Categoria<select value={editForm.category||''} onChange={e=>setEditForm({...editForm,category:e.target.value})}>{categories.map(x=><option key={x}>{x}</option>)}</select></label><label>Pessoa<select value={editForm.person||'Rafael'} onChange={e=>setEditForm({...editForm,person:e.target.value})}><option value="Rafael">Você</option><option value="Mariana">Parceiro(a)</option><option>Casal</option></select></label></div><div className="edit-modal-actions"><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar alterações</button></div></form></div>}
  </div>;
}

function BudgetsPage(){
  const initial:any[]=[];
  const [items,setItems]=useState<any[]>(initial); const [editing,setEditing]=useState<any|null>(null); const [tx,setTx]=useState<any[]>(transactions); const [period,setPeriod]=useState(()=>new Intl.DateTimeFormat('en-CA').format(new Date()).slice(0,7));
  const categories=['Moradia','Alimentação','Mercado','Restaurante','Delivery','Transporte','Combustível','Aluguel','Condomínio','Internet','Luz','Água','Telefone','Saúde','Educação','Filhos','Viagens','Lazer','Compras','Assinaturas','Investimentos','Dívidas','Seguros','Impostos','Outros'];
  useEffect(()=>{const saved=localStorage.getItem('juntos-budgets');if(saved)setItems(JSON.parse(saved));const load=()=>{const data=localStorage.getItem('juntos-transactions');setTx(data?JSON.parse(data):transactions)};load();window.addEventListener('juntos-transactions-updated',load);return()=>window.removeEventListener('juntos-transactions-updated',load)},[]);
  const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-budgets',JSON.stringify(next))}; const spent=(b:any)=>tx.filter(t=>t.type==='out'&&(t.category===b.category||(b.theme==='fixed'&&['Aluguel','Condomínio','Internet','Luz','Água','Telefone'].includes(t.category)))).reduce((s,t)=>s+Number(t.value),0);
  const openNew=()=>setEditing({id:Date.now(),name:'',category:'Lazer',limit:'',theme:'leisure',icon:'🎯',color:'#7c3aed',isNew:true}); const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,limit:Number(String(editing.limit).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;if(!item.name.trim()||item.limit<=0)return;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Orçamento criado com sucesso.':'Orçamento atualizado com sucesso.')}; const remove=async()=>{if(editing&&!editing.isNew&&await confirmDialog(`Excluir “${editing.name}”?`)){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Orçamento excluído.')}};
  const totalLimit=items.reduce((s,x)=>s+Number(x.limit),0),totalSpent=items.reduce((s,x)=>s+spent(x),0);
  return <div className="page-stack budgets-page"><div className="page-heading"><div><p>Planejamento mensal</p><h1>Orçamentos</h1><span>Escolha onde gastar e respeite seus limites.</span></div><div className="budget-actions"><input className="ghost toolbar-month" type="month" value={period} onChange={e=>setPeriod(e.target.value)}/><button className="primary" onClick={openNew}><Plus size={18}/> Novo orçamento</button></div></div><div className="metrics-grid compact"><MetricCard label="Limite planejado" value={brl(totalLimit)} detail="Todos os temas" icon={Target} tone="purple"/><MetricCard label="Valor utilizado" value={brl(totalSpent)} detail={`${Math.round(totalSpent/totalLimit*100)||0}% do total`} icon={TrendingDown} tone="negative"/><MetricCard label="Ainda disponível" value={brl(Math.max(0,totalLimit-totalSpent))} detail="Para o restante do mês" icon={WalletCards} tone="positive"/></div><div className="budget-grid">{items.map(b=>{const used=spent(b),pct=Math.min(100,Math.round(used/b.limit*100)||0),remaining=b.limit-used;return <article className={`card budget-card ${remaining<0?'over':''}`} key={b.id}><button className="budget-edit" onClick={()=>setEditing({...b,limit:String(b.limit).replace('.',',')})} aria-label={`Editar ${b.name}`}><MoreHorizontal size={18}/></button><div className="budget-icon" style={{background:`${b.color}18`,color:b.color}}>{b.icon}</div><span>{b.theme==='fixed'?'DESPESA FIXA':b.theme==='leisure'?'LAZER':b.theme==='saving'?'RESERVA':'VARIÁVEL'}</span><h3>{b.name}</h3><small>{b.category}</small><div className="budget-values"><b>{brl(used)}</b><span>de {brl(b.limit)}</span></div><div className="progress"><span style={{width:`${pct}%`,background:remaining<0?'#c13d4e':b.color}}/></div><div className="budget-foot"><span>{pct}% utilizado</span><strong className={remaining<0?'down':'up'}>{remaining<0?`${brl(Math.abs(remaining))} acima`:`${brl(remaining)} disponível`}</strong></div></article>})}</div>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal budget-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO ORÇAMENTO':'EDITAR ORÇAMENTO'}</span><h2>{editing.isNew?'Criar limite de gastos':'Atualizar limite'}</h2><p>Escolha o tema e quanto deseja gastar.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="budget-edit-grid"><label className="field-full">Nome do orçamento<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} placeholder="Ex.: Lazer de fim de semana" required/></label><label>Tema<select value={editing.theme} onChange={e=>setEditing({...editing,theme:e.target.value})}><option value="fixed">Despesa fixa</option><option value="leisure">Lazer</option><option value="variable">Gasto variável</option><option value="saving">Reserva</option></select></label><label>Categoria<select value={editing.category} onChange={e=>setEditing({...editing,category:e.target.value})}>{categories.map(x=><option key={x}>{x}</option>)}</select></label><label>Limite mensal<input value={editing.limit} onChange={e=>setEditing({...editing,limit:e.target.value.replace(/[^0-9,.]/g,'')})} placeholder="0,00" inputMode="decimal" required/></label><label>Ícone<input value={editing.icon} onChange={e=>setEditing({...editing,icon:e.target.value})} maxLength={4}/></label><label>Cor<input type="color" value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir orçamento</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar orçamento</button></div></form></div>}
  </div>
}
function AccountsPage({people,setPeople,balances,setBalances}:{people:any;setPeople:any;balances:any;setBalances:any}) {
  const [accounts,setAccounts]=useState<any[]>([]); const [editing,setEditing]=useState<any|null>(null); const [transfer,setTransfer]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-accounts');setAccounts(saved?JSON.parse(saved):[])},[]);
  const persist=(next:any[])=>{setAccounts(next);localStorage.setItem('juntos-accounts',JSON.stringify(next));const nextBalances={...balances,couple:0,rafael:0,mariana:0,investments:0};next.forEach(a=>{if(a.id in nextBalances)nextBalances[a.id]=Number(a.value)});setBalances(nextBalances);localStorage.setItem('juntos-balances',JSON.stringify(nextBalances))};
  const openNew=()=>setEditing({id:'account-'+Date.now(),name:'',bank:'',type:'Conta corrente',value:'',color:'violet',isNew:true});
  const saveAccount=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(editing.value).replace(/[.]/g,'').replace(',','.'));if(!editing.name.trim()||!editing.bank.trim()||Number.isNaN(value))return;const account={...editing,name:editing.name.trim(),bank:editing.bank.trim(),value};delete account.isNew;const next=editing.isNew?[...accounts,account]:accounts.map(a=>a.id===account.id?account:a);persist(next);if(account.id==='rafael')setPeople({...people,Rafael:{...people.Rafael,name:account.name}});if(account.id==='mariana')setPeople({...people,Mariana:{...people.Mariana,name:account.name}});setEditing(null);appAction(editing.isNew?'Conta criada com sucesso.':'Conta atualizada em todo o aplicativo.')};
  const deleteAccount=async()=>{if(!editing||!await confirmDialog(`Excluir a conta ${editing.name}?`))return;persist(accounts.filter(a=>a.id!==editing.id));setEditing(null);appAction('Conta excluída.')};
  const saveTransfer=async(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(transfer.value).replace(/[.]/g,'').replace(',','.'));if(!transfer.from||!transfer.to||transfer.from===transfer.to||value<=0)return;const origin=accounts.find(a=>a.id===transfer.from);if(!origin||origin.value<value){await alertDialog('Saldo insuficiente na conta de origem.');return}persist(accounts.map(a=>a.id===transfer.from?{...a,value:a.value-value}:a.id===transfer.to?{...a,value:a.value+value}:a));setTransfer(null);appAction('Transferência concluída com sucesso.')};
  const total=accounts.reduce((sum,a)=>sum+Number(a.value||0),0);
  return <div className="page-stack"><div className="page-heading"><div><p>Patrimônio</p><h1>Contas</h1><span>Todos os saldos em um só lugar.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Nova conta</button></div><div className="account-grid">{accounts.length?accounts.map(a=><article className="card account" key={a.id}><div className={`bank-icon ${a.color}`}><Landmark/></div><button className="icon-button" onClick={()=>setEditing({...a,value:String(a.value).replace('.',',')})} aria-label={`Editar ${a.name}`}><MoreHorizontal size={18}/></button><span>{a.bank}</span><h3>{a.name}</h3><small>{a.type}</small><strong>{brl(a.value)}</strong><div className="account-foot"><span>Sem movimentações</span></div></article>):<div className="organizer-empty">Nenhuma conta cadastrada.</div>}</div><section className="card table-card"><div className="section-title"><div><h3>Visão consolidada</h3><p>Saldo por instituição</p></div><button className="ghost" disabled={accounts.length<2} onClick={()=>setTransfer({from:accounts[0]?.id||'',to:accounts[1]?.id||'',value:''})}>Transferir entre contas</button></div><div className="metrics-grid compact"><MetricCard label="Saldo total" value={brl(total)} detail={`${accounts.length} contas cadastradas`} icon={WalletCards} tone="purple"/><MetricCard label="Entradas" value={brl(0)} detail="Sem movimentações" icon={TrendingUp} tone="positive"/><MetricCard label="Saídas" value={brl(0)} detail="Sem movimentações" icon={TrendingDown} tone="negative"/></div><div className="bar-wrap"><ResponsiveContainer width="100%" height="100%"><ReBarChart data={accounts} layout="vertical" margin={{left:20,right:30}}><CartesianGrid strokeDasharray="4 4" horizontal={false}/><XAxis type="number" hide/><YAxis type="category" dataKey="bank" axisLine={false} tickLine={false}/><Tooltip formatter={(v)=>brl(Number(v))}/><Bar dataKey="value" fill="#7f2854" radius={[0,8,8,0]}/></ReBarChart></ResponsiveContainer></div></section>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal account-editor" onSubmit={saveAccount}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVA CONTA':'EDITAR CONTA'}</span><h2>{editing.isNew?'Adicionar conta':'Configurar conta'}</h2><p>Atualize todas as informações e o saldo.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X size={19}/></button></div><div className="account-edit-grid"><label>Nome da conta<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} required/></label><label>Instituição<input value={editing.bank} onChange={e=>setEditing({...editing,bank:e.target.value})} placeholder="Ex.: Nubank" required/></label><label>Tipo<select value={editing.type} onChange={e=>setEditing({...editing,type:e.target.value})}><option>Conta corrente</option><option>Conta individual</option><option>Carteira</option><option>Investimentos</option><option>Poupança</option></select></label><label>Saldo<input value={editing.value} onChange={e=>setEditing({...editing,value:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal" required/></label><label>Cor<select value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}><option value="violet">Roxo</option><option value="orange">Laranja</option><option value="amber">Amarelo</option><option value="dark">Preto</option></select></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger delete-account" onClick={deleteAccount}>Excluir conta</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar conta</button></div></form></div>}
    {transfer&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setTransfer(null)}><form className="modal transfer-modal" onSubmit={saveTransfer}><div className="edit-modal-head"><div><span>MOVIMENTAÇÃO INTERNA</span><h2>Transferir entre contas</h2><p>O valor será debitado da origem e creditado no destino.</p></div><button type="button" className="icon-button" onClick={()=>setTransfer(null)}><X size={19}/></button></div><div className="account-edit-grid"><label>Conta de origem<select value={transfer.from} onChange={e=>setTransfer({...transfer,from:e.target.value})}>{accounts.map(a=><option value={a.id} key={a.id}>{a.name} — {brl(a.value)}</option>)}</select></label><label>Conta de destino<select value={transfer.to} onChange={e=>setTransfer({...transfer,to:e.target.value})}>{accounts.map(a=><option value={a.id} key={a.id}>{a.name}</option>)}</select></label><label className="field-full">Valor da transferência<input value={transfer.value} onChange={e=>setTransfer({...transfer,value:e.target.value.replace(/[^0-9,.]/g,'')})} placeholder="0,00" inputMode="decimal" required/></label></div><div className="edit-modal-actions"><span/><button type="button" className="ghost" onClick={()=>setTransfer(null)}>Cancelar</button><button className="primary">Confirmar transferência</button></div></form></div>}
  </div>
}

function CardsPage({people}:{people:any}){
  const defaultCards:any[]=[];
  const [cards,setCards]=useState<any[]>(defaultCards); const [selectedId,setSelectedId]=useState('nubank-4821'); const [editing,setEditing]=useState<any|null>(null); const [details,setDetails]=useState(false); const [purchases,setPurchases]=useState<any[]>(transactions.filter(t=>t.type==='out'));
  useEffect(()=>{const saved=localStorage.getItem('juntos-cards');if(saved){const parsed=JSON.parse(saved);setCards(parsed);if(parsed[0])setSelectedId(parsed[0].id)}const load=()=>{const tx=localStorage.getItem('juntos-transactions');setPurchases((tx?JSON.parse(tx):transactions).filter((t:any)=>t.type==='out'))};load();window.addEventListener('juntos-transactions-updated',load);return()=>window.removeEventListener('juntos-transactions-updated',load)},[]);
  const persist=(next:any[])=>{setCards(next);localStorage.setItem('juntos-cards',JSON.stringify(next))}; const card=cards.find(c=>c.id===selectedId)||cards[0];
  const cardLabel=(item:any)=>item.last4 ? item.bank+' final '+item.last4 : item.bank;
  const cardPurchases=card?purchases.filter(transaction=>transaction.card===cardLabel(card)):[];
  const openNew=()=>setEditing({id:'card-'+Date.now(),bank:'',last4:'',holder:people.Rafael.name.toUpperCase()||'',invoice:'0',limit:'0',closing:new Date().toISOString().slice(0,10),future:'0',color:'purple',isNew:true});
  const saveCard=(e:React.FormEvent)=>{e.preventDefault();const clean={...editing,invoice:Number(String(editing.invoice).replace(/[.]/g,'').replace(',','.')),limit:Number(String(editing.limit).replace(/[.]/g,'').replace(',','.')),future:Number(String(editing.future).replace(/[.]/g,'').replace(',','.'))};delete clean.isNew;if(!clean.bank.trim()||(clean.last4&&clean.last4.length!==4)||!clean.holder.trim()||clean.limit<=0||!clean.closing){appAction('Preencha os dados obrigatórios e informe um limite maior que zero.');return}const next=editing.isNew?[...cards,clean]:cards.map(c=>c.id===clean.id?clean:c);persist(next);setSelectedId(clean.id);setEditing(null);appAction(editing.isNew?'Cartão criado com sucesso.':'Cartão atualizado com sucesso.')};
  const removeCard=async()=>{if(!editing||!await confirmDialog(`Excluir o cartão ${editing.bank}?`))return;const next=cards.filter(c=>c.id!==editing.id);persist(next);setSelectedId(next[0]?.id||'');setEditing(null);appAction('Cartão excluído.')};
  const pay=async()=>{if(!card||!await confirmDialog(`Confirmar pagamento de ${brl(card.invoice)}?`))return;persist(cards.map(c=>c.id===card.id?{...c,invoice:0}:c));appAction('Fatura paga com sucesso.')};
  if(!card)return <div className="page-stack"><div className="page-heading"><div><p>Crédito</p><h1>Cartões</h1><span>Nenhum cartão cadastrado.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Novo cartão</button></div>{editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal card-editor" onSubmit={saveCard}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO CARTÃO':'EDITAR CARTÃO'}</span><h2>{editing.isNew?'Adicionar cartão':'Configurar cartão'}</h2><p>Edite todos os dados, limites e datas.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="card-edit-grid"><label>Instituição<input value={editing.bank} onChange={e=>setEditing({...editing,bank:e.target.value})} required/></label><label>Últimos 4 dígitos (opcional)<input value={editing.last4||''} maxLength={4} onChange={e=>setEditing({...editing,last4:e.target.value.replace(/\D/g,'')})} placeholder="Ex.: 1234" inputMode="numeric"/></label><label>Titular<input value={editing.holder} onChange={e=>setEditing({...editing,holder:e.target.value})} required/></label><label>Fatura atual<input value={editing.invoice} onChange={e=>setEditing({...editing,invoice:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Limite total<input value={editing.limit} onChange={e=>setEditing({...editing,limit:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Próximo fechamento<input type="date" value={editing.closing} onChange={e=>setEditing({...editing,closing:e.target.value})}/></label><label>Parcelas futuras<input value={editing.future} onChange={e=>setEditing({...editing,future:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Cor<select value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}><option value="purple">Roxo</option><option value="wine">Vinho</option><option value="blue">Azul</option><option value="black">Preto</option></select></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={removeCard}>Excluir cartão</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar cartão</button></div></form></div>}</div>;
  const used=Math.min(100,Math.round(card.invoice/card.limit*100)||0); const closingLabel=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long'}).format(new Date(card.closing+'T12:00:00'));
  return <div className="page-stack"><div className="page-heading"><div><p>Crédito</p><h1>Cartões</h1><span>Limites e faturas sob controle.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Novo cartão</button></div>{cards.length>1&&<div className="card-tabs">{cards.map(c=><button className={c.id===card.id?'active':''} onClick={()=>setSelectedId(c.id)} key={c.id}>{c.bank} {c.last4?`•••• ${c.last4}`:'Sem final'}</button>)}</div>}<div className="cards-layout"><button className={`credit-card visual-nubank card-visual-button ${card.color}`} onClick={()=>setEditing({...card,invoice:String(card.invoice).replace('.',','),limit:String(card.limit).replace('.',','),future:String(card.future).replace('.',',')})}><div><span>{card.bank}</span><CreditCard/></div><b>{card.last4?`•••• •••• •••• ${card.last4}`:'Número não informado'}</b><div><span>{card.holder}</span></div><small>Clique para editar</small></button><section className="card invoice"><span>Fatura atual</span><h2>{brl(card.invoice)}</h2><div className="progress"><span style={{width:`${used}%`}}/></div><div><span>Limite usado: {used}%</span><b>Disponível: {brl(Math.max(0,card.limit-card.invoice))}</b></div><button className="primary" onClick={pay} disabled={card.invoice<=0}>{card.invoice>0?'Pagar fatura':'Fatura paga'}</button></section><section className="card invoice"><span>Próximo fechamento</span><h2>{closingLabel}</h2><div className="invoice-alert"><Lightbulb/> Suas parcelas futuras somam {brl(card.future)}</div><button className="ghost" onClick={()=>setDetails(true)}>Ver detalhes</button></section></div><section className="card table-card"><div className="section-title"><div><h3>Compras no cartão</h3><p>Fatura atual</p></div><button className="text-button" onClick={()=>appAction({page:'Transações'})}>Ver fatura completa <ArrowRight size={15}/></button></div><div className="transaction-list large">{cardPurchases.length?cardPurchases.map(t=><div className="transaction" key={t.id}><div className="transaction-icon out">{t.icon}</div><div className="transaction-name"><b>{displayTitle(people,t.title)}</b><span>{t.category}</span><small className="transaction-mobile-date">{t.date}</small></div><span className="person-pill">{displayPerson(people,t.person)}</span><div className="transaction-date">{t.date}</div><strong>− {brl(t.value)}</strong></div>):<div className="organizer-empty">Nenhuma compra cadastrada neste cartão.</div>}</div></section>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal card-editor" onSubmit={saveCard}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO CARTÃO':'EDITAR CARTÃO'}</span><h2>{editing.isNew?'Adicionar cartão':'Configurar cartão'}</h2><p>Edite todos os dados, limites e datas.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="card-edit-grid"><label>Instituição<input value={editing.bank} onChange={e=>setEditing({...editing,bank:e.target.value})} required/></label><label>Últimos 4 dígitos (opcional)<input value={editing.last4||''} maxLength={4} onChange={e=>setEditing({...editing,last4:e.target.value.replace(/\D/g,'')})} placeholder="Ex.: 1234" inputMode="numeric"/></label><label>Titular<input value={editing.holder} onChange={e=>setEditing({...editing,holder:e.target.value})} required/></label><label>Fatura atual<input value={editing.invoice} onChange={e=>setEditing({...editing,invoice:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Limite total<input value={editing.limit} onChange={e=>setEditing({...editing,limit:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Próximo fechamento<input type="date" value={editing.closing} onChange={e=>setEditing({...editing,closing:e.target.value})}/></label><label>Parcelas futuras<input value={editing.future} onChange={e=>setEditing({...editing,future:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Cor<select value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}><option value="purple">Roxo</option><option value="wine">Vinho</option><option value="blue">Azul</option><option value="black">Preto</option></select></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={removeCard}>Excluir cartão</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar cartão</button></div></form></div>}
    {details&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setDetails(false)}><div className="modal card-details"><div className="edit-modal-head"><div><span>RESUMO DO CARTÃO</span><h2>{card.bank} {card.last4?`•••• ${card.last4}`:''}</h2></div><button className="icon-button" onClick={()=>setDetails(false)}><X/></button></div><div className="details-list"><div><span>Fatura atual</span><b>{brl(card.invoice)}</b></div><div><span>Limite total</span><b>{brl(card.limit)}</b></div><div><span>Limite disponível</span><b>{brl(Math.max(0,card.limit-card.invoice))}</b></div><div><span>Próximo fechamento</span><b>{closingLabel}</b></div><div><span>Parcelas futuras</span><b>{brl(card.future)}</b></div></div><div className="edit-modal-actions"><span/><button className="primary" onClick={()=>setDetails(false)}>Fechar</button></div></div></div>}
  </div>
}

function GoalsPage(){
  const initialGoals:any[]=[];
  const [items,setItems]=useState<any[]>(initialGoals); const [editing,setEditing]=useState<any|null>(null); const [contribution,setContribution]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-goals');if(saved)setItems(JSON.parse(saved))},[]); const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-goals',JSON.stringify(next));window.dispatchEvent(new Event('juntos-goals-updated'))};
  const openNew=()=>setEditing({id:Date.now(),title:'',emoji:'🎯',current:'0',total:'',color:'#7c3aed',date:'Dez 2026',isNew:true});
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,current:Number(String(editing.current).replace(/[.]/g,'').replace(',','.')),total:Number(String(editing.total).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;if(!item.title.trim()||item.total<=0)return;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Meta criada com sucesso.':'Meta atualizada com sucesso.')};
  const remove=async()=>{if(editing&&!editing.isNew&&await confirmDialog(`Excluir a meta “${editing.title}”?`)){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Meta excluída.')}};
  const addMoney=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(contribution.value).replace(/[.]/g,'').replace(',','.'));if(value<=0)return;persist(items.map(x=>x.id===contribution.goal.id?{...x,current:x.current+value}:x));setContribution(null);appAction('Dinheiro adicionado à meta.')};
  return <div className="page-stack"><div className="page-heading"><div><p>Meus objetivos</p><h1>Metas</h1><span>Cada passo aproxima você do futuro.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Nova meta</button></div><div className="goal-page-grid">{items.map(g=>{const pct=Math.min(100,Math.round(g.current/g.total*100)||0);return <article className="card big-goal" key={g.id}><button className="goal-cover goal-cover-button" style={{background:`linear-gradient(135deg,${g.color},#24131e)`}} onClick={()=>setEditing({...g,current:String(g.current).replace('.',','),total:String(g.total).replace('.',',')})}><span>{g.emoji}</span><b>{pct}%</b><small>Clique para editar</small></button><div className="goal-body"><h3>{g.title}</h3><p>Previsão: {g.date}</p><div className="progress"><span style={{width:`${pct}%`,background:g.color}}/></div><div><b>{brl(g.current)}</b><span>Faltam {brl(Math.max(0,g.total-g.current))}</span></div><button className="ghost" onClick={()=>setContribution({goal:g,value:''})}>Adicionar dinheiro</button></div></article>})}</div>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal goal-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVA META':'EDITAR META'}</span><h2>{editing.isNew?'Criar uma meta':'Atualizar meta'}</h2><p>Personalize o objetivo e acompanhe o progresso.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="goal-edit-grid"><label className="field-full">Nome da meta<input value={editing.title} onChange={e=>setEditing({...editing,title:e.target.value})} placeholder="Ex.: Viagem para Itália" required/></label><label>Ícone<input value={editing.emoji} onChange={e=>setEditing({...editing,emoji:e.target.value})} maxLength={4}/></label><label>Cor<input type="color" value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}/></label><label>Valor guardado<input value={editing.current} onChange={e=>setEditing({...editing,current:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal"/></label><label>Valor da meta<input value={editing.total} onChange={e=>setEditing({...editing,total:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal" required/></label><label className="field-full">Previsão de conclusão<input value={editing.date} onChange={e=>setEditing({...editing,date:e.target.value})} placeholder="Ex.: Novembro de 2027"/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir meta</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar meta</button></div></form></div>}
    {contribution&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setContribution(null)}><form className="modal contribution-modal" onSubmit={addMoney}><div className="edit-modal-head"><div><span>NOVO APORTE</span><h2>Adicionar dinheiro</h2><p>{contribution.goal.emoji} {contribution.goal.title}</p></div><button type="button" className="icon-button" onClick={()=>setContribution(null)}><X/></button></div><div className="goal-edit-grid"><label className="field-full">Valor do aporte<input value={contribution.value} onChange={e=>setContribution({...contribution,value:e.target.value.replace(/[^0-9,.]/g,'')})} placeholder="0,00" inputMode="decimal" autoFocus required/></label></div><div className="edit-modal-actions"><span/><button type="button" className="ghost" onClick={()=>setContribution(null)}>Cancelar</button><button className="primary">Confirmar aporte</button></div></form></div>}
  </div>
}

function CalendarPage({people}:{people:any}){
  const initialEvents:any[]=[];
  const [month,setMonth]=useState(new Date()); const [events,setEvents]=useState<any[]>(initialEvents); const [editing,setEditing]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-calendar-events');if(saved)setEvents(JSON.parse(saved))},[]);
  const persist=(next:any[])=>{setEvents(next);localStorage.setItem('juntos-calendar-events',JSON.stringify(next));window.dispatchEvent(new Event('juntos-calendar-updated'))};
  const year=month.getFullYear(),monthIndex=month.getMonth(),daysInMonth=new Date(year,monthIndex+1,0).getDate(),startDay=new Date(year,monthIndex,1).getDay(); const cells=Array.from({length:42},(_,i)=>i-startDay+1); const monthKey=`${year}-${String(monthIndex+1).padStart(2,'0')}`;
  const openNew=(date?:string)=>setEditing({id:Date.now(),title:'',date:date||`${monthKey}-${String(Math.min(new Date().getDate(),daysInMonth)).padStart(2,'0')}`,type:'bill',value:'',person:'Rafael',notes:'',isNew:true});
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,value:Number(String(editing.value||0).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;persist(editing.isNew?[...events,item]:events.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Evento criado no calendário.':'Evento atualizado com sucesso.')};
  const remove=async()=>{if(editing&&!editing.isNew&&await confirmDialog(`Excluir “${editing.title}”?`)){persist(events.filter(x=>x.id!==editing.id));setEditing(null);appAction('Evento excluído do calendário.')}};
  const monthEvents=events.filter(e=>e.date.startsWith(monthKey)); const upcoming=[...events].filter(e=>e.date>=`${monthKey}-01`).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5); const title=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(month).replace(/^./,x=>x.toUpperCase());
  return <div className="page-stack"><div className="page-heading"><div><p>Minha agenda</p><h1>Calendário financeiro</h1><span>Nenhum compromisso fica para trás.</span></div><button className="primary" onClick={()=>openNew()}><Plus size={18}/> Novo evento</button></div><div className="calendar-layout"><section className="card calendar"><div className="calendar-head"><button className="icon-button" onClick={()=>setMonth(new Date(year,monthIndex-1,1))} aria-label="Mês anterior">‹</button><h3>{title}</h3><button className="icon-button" onClick={()=>setMonth(new Date(year,monthIndex+1,1))} aria-label="Próximo mês">›</button><button className="ghost" onClick={()=>setMonth(new Date())}>Hoje</button></div><div className="weekdays">{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=><b key={x}>{x}</b>)}</div><div className="days">{cells.map((day,i)=>{const valid=day>=1&&day<=daysInMonth;const date=valid?`${monthKey}-${String(day).padStart(2,'0')}`:'';const dayEvents=valid?monthEvents.filter(e=>e.date===date):[];return <div className={!valid?'muted':date===new Date().toISOString().slice(0,10)?'today':''} key={i} onDoubleClick={()=>valid&&openNew(date)}><button className="day-number" onClick={()=>valid&&openNew(date)} disabled={!valid}>{valid?day:''}</button>{dayEvents.map(e=><button className={`calendar-event ${e.type}`} onClick={()=>setEditing({...e,value:String(e.value).replace('.',',')})} key={e.id}>{e.title}</button>)}</div>})}</div><small className="calendar-hint">Clique no número do dia para adicionar. Clique no evento para editar.</small></section><aside className="card agenda"><h3>Próximos eventos</h3>{upcoming.length?upcoming.map(e=><button className="agenda-date" onClick={()=>setEditing({...e,value:String(e.value).replace('.',',')})} key={e.id}><b>{e.date.slice(-2)}</b><span>{new Intl.DateTimeFormat('pt-BR',{weekday:'short'}).format(new Date(e.date+'T12:00:00')).toUpperCase()}<small>{e.title}</small></span><strong>{e.value?brl(e.value):'—'}</strong></button>):<p className="agenda-empty">Nenhum evento agendado.</p>}<div className="ai-mini"><Sparkles/><p><b>Agenda organizada!</b> Clique em qualquer compromisso para atualizar.</p></div></aside></div>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal calendar-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO EVENTO':'EDITAR EVENTO'}</span><h2>{editing.isNew?'Adicionar compromisso':'Atualizar compromisso'}</h2><p>Organize datas, valores e responsáveis.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="calendar-edit-grid"><label className="field-full">Título<input value={editing.title} onChange={e=>setEditing({...editing,title:e.target.value})} placeholder="Ex.: Conta de energia" required/></label><label>Data<input type="date" value={editing.date} onChange={e=>setEditing({...editing,date:e.target.value})} required/></label><label>Tipo<select value={editing.type} onChange={e=>setEditing({...editing,type:e.target.value})}><option value="bill">Conta</option><option value="income">Receita</option><option value="card">Cartão</option><option value="sub">Assinatura</option><option value="goal">Meta</option></select></label><label>Valor<input value={editing.value} onChange={e=>setEditing({...editing,value:e.target.value.replace(/[^0-9,.]/g,'')})} placeholder="0,00" inputMode="decimal"/></label><label>Responsável<select value={editing.person} onChange={e=>setEditing({...editing,person:e.target.value})}><option value="Rafael">Você</option></select></label><label className="field-full">Observações<textarea value={editing.notes||''} onChange={e=>setEditing({...editing,notes:e.target.value})} placeholder="Detalhes opcionais" rows={3}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir evento</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar evento</button></div></form></div>}
  </div>
}

function SubscriptionsPage(){
  const initial:any[]=[];
  const [items,setItems]=useState<any[]>(initial); const [editing,setEditing]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-subscriptions');if(saved)setItems(JSON.parse(saved))},[]); const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-subscriptions',JSON.stringify(next))};
  const openNew=()=>setEditing({id:Date.now(),name:'',category:'Entretenimento',value:'',next:new Intl.DateTimeFormat('en-CA').format(new Date()),icon:'★',active:true,isNew:true});
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,value:Number(String(editing.value).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;if(!item.name.trim()||item.value<0)return;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Assinatura criada com sucesso.':'Assinatura atualizada com sucesso.')};
  const remove=async()=>{if(editing&&!editing.isNew&&await confirmDialog(`Excluir “${editing.name}”?`)){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Assinatura excluída.')}}; const active=items.filter(x=>x.active); const monthly=active.reduce((sum,x)=>sum+Number(x.value),0); const paused=items.filter(x=>!x.active).reduce((sum,x)=>sum+Number(x.value),0);
  return <div className="page-stack"><div className="page-heading"><div><p>Gastos recorrentes</p><h1>Assinaturas</h1><span>Pequenos valores também contam.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Nova assinatura</button></div><div className="metrics-grid compact"><MetricCard label="Total mensal" value={brl(monthly)} detail={`${active.length} assinaturas ativas`} icon={Zap} tone="purple"/><MetricCard label="Custo anual" value={brl(monthly*12)} detail="Projeção para 12 meses" icon={CalendarDays}/><MetricCard label="Economia com pausas" value={brl(paused)} detail={`${items.length-active.length} pausadas`} icon={TrendingDown} tone="positive"/></div><div className="subscription-grid">{items.map(s=><article className={`card subscription ${!s.active?'paused':''}`} key={s.id}><div className="sub-logo">{s.icon}</div><button className="icon-button" onClick={()=>setEditing({...s,value:String(s.value).replace('.',',')})}><MoreHorizontal size={17}/></button><h3>{s.name}</h3><p>{s.category}</p><strong>{brl(Number(s.value))}<small>/mês</small></strong><div><span>Próxima cobrança</span><b>{new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(s.next+'T12:00:00')).replace('.','')}</b></div><span className={`subscription-status ${s.active?'active':'paused'}`}>{s.active?'Ativa':'Pausada'}</span><button className="ghost" onClick={()=>setEditing({...s,value:String(s.value).replace('.',',')})}>Gerenciar</button></article>)}</div>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal subscription-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVA ASSINATURA':'EDITAR ASSINATURA'}</span><h2>{editing.isNew?'Adicionar assinatura':'Gerenciar assinatura'}</h2><p>Atualize cobrança, categoria e situação.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="subscription-edit-grid"><label className="field-full">Nome<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} placeholder="Ex.: Netflix" required/></label><label>Categoria<select value={editing.category} onChange={e=>setEditing({...editing,category:e.target.value})}><option>Entretenimento</option><option>Música</option><option>Saúde</option><option>Armazenamento</option><option>Educação</option><option>Produtividade</option><option>Transporte</option><option>Outros</option></select></label><label>Ícone<input value={editing.icon} onChange={e=>setEditing({...editing,icon:e.target.value})} maxLength={3}/></label><label>Valor mensal<input value={editing.value} onChange={e=>setEditing({...editing,value:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal" required/></label><label>Próxima cobrança<input type="date" value={editing.next} onChange={e=>setEditing({...editing,next:e.target.value})} required/></label><div className="subscription-active field-full"><span><b>Assinatura ativa</b><small>Desative para pausar a cobrança nos totais</small></span><button type="button" className={`toggle ${editing.active?'on':''}`} onClick={()=>setEditing({...editing,active:!editing.active})}><i/></button></div></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir assinatura</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar assinatura</button></div></form></div>}
  </div>
}

function ReportsPage({people}:{people:any}){
  const [view,setView]=useState('Mensal'); const [tx,setTx]=useState<any[]>(transactions); const [accounts,setAccounts]=useState<any[]>([]); const [cards,setCards]=useState<any[]>([]);
  useEffect(()=>{const savedTx=localStorage.getItem('juntos-transactions'),savedAccounts=localStorage.getItem('juntos-accounts'),savedCards=localStorage.getItem('juntos-cards');if(savedTx)setTx(JSON.parse(savedTx));if(savedAccounts)setAccounts(JSON.parse(savedAccounts));if(savedCards)setCards(JSON.parse(savedCards))},[]);
  const income=tx.filter(t=>t.type==='in').reduce((s,t)=>s+Number(t.value),0),expense=tx.filter(t=>t.type==='out').reduce((s,t)=>s+Number(t.value),0); const categories=Object.values(tx.filter(t=>t.type==='out').reduce((acc:any,t:any)=>{acc[t.category]??={name:t.category,value:0};acc[t.category].value+=Number(t.value);return acc},{})) as any[]; const categoryColors=['#752548','#9f4a78','#7c3aed','#d78faf','#db8b24','#0f9f6e'];
  const rows=()=>view==='Por categoria'?categories.map((x:any)=>[x.name,brl(x.value)]):view==='Por cartão'?cards.map((c:any)=>[c.bank+' •••• '+c.last4,brl(c.invoice),brl(c.limit)]):view==='Por banco'?accounts.map((a:any)=>[a.bank,a.name,brl(a.value)]):view==='Anual'?cashflow.map((x:any)=>[x.m,brl(x.receita),brl(x.despesa),brl(x.receita-x.despesa)]):tx.map((t:any)=>[t.date,displayTitle(people,t.title),t.category,displayPerson(people,t.person),t.type==='in'?brl(t.value):'- '+brl(t.value)]);
  const headers=()=>view==='Por categoria'?['Categoria','Total']:view==='Por cartão'?['Cartão','Fatura','Limite']:view==='Por banco'?['Banco','Conta','Saldo']:view==='Anual'?['Mês','Receitas','Despesas','Resultado']:['Data','Descrição','Categoria','Pessoa','Valor'];
  const exportExcel=()=>{const table=[headers(),...rows()];const html=`<table>${table.map((r,i)=>`<tr>${r.map(c=>`<${i?'td':'th'}>${c}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table>`;const blob=new Blob([html],{type:'application/vnd.ms-excel;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`relatorio-${view.toLowerCase().replace(/ /g,'-')}.xls`;a.click();URL.revokeObjectURL(url);appAction('Relatório Excel exportado.')};
  const exportPdf=()=>{const win=window.open('','_blank','width=900,height=700');if(!win)return;win.document.write(`<html><head><title>Relatório ${view}</title><style>body{font-family:Arial;padding:32px;color:#241820}h1{color:#7f2854}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}th{background:#f6eff2}</style></head><body><h1>Juntos Finance — ${view}</h1><p>Receitas: ${brl(income)} | Despesas: ${brl(expense)} | Resultado: ${brl(income-expense)}</p><table><thead><tr>${headers().map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows().map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);win.document.close()};
  return <div className="page-stack reports-page"><div className="page-heading"><div><p>Análises financeiras</p><h1>Relatórios</h1><span>Entenda seus números e tome decisões melhores.</span></div><div className="report-export"><button className="ghost" onClick={exportPdf}><Download size={17}/> Exportar PDF</button><button className="primary" onClick={exportExcel}><Download size={17}/> Excel</button></div></div><div className="report-tabs">{['Mensal','Anual','Por categoria','Por cartão','Por banco'].map(x=><button className={view===x?'active':''} onClick={()=>setView(x)} key={x}>{x}</button>)}</div><div className="metrics-grid compact"><MetricCard label="Receitas" value={brl(income)} detail="Período selecionado" icon={TrendingUp} tone="positive"/><MetricCard label="Despesas" value={brl(expense)} detail="Período selecionado" icon={TrendingDown} tone="negative"/><MetricCard label="Resultado" value={brl(income-expense)} detail={income-expense>=0?'Positivo':'Negativo'} icon={WalletCards} tone="purple"/></div>{view==='Anual'&&<section className="card report-chart"><h3>Visão anual</h3><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><ReBarChart data={cashflow}><CartesianGrid vertical={false} stroke="#eee7eb"/><XAxis dataKey="m" axisLine={false} tickLine={false}/><YAxis hide/><Tooltip formatter={v=>brl(Number(v))}/><Bar dataKey="receita" fill="#2f9961" radius={[5,5,0,0]}/><Bar dataKey="despesa" fill="#8b263f" radius={[5,5,0,0]}/></ReBarChart></ResponsiveContainer></div></section>}{view==='Por categoria'&&<section className="card report-chart category-report"><h3>Despesas por categoria</h3><div className="report-category-layout"><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={categories} dataKey="value" nameKey="name" innerRadius={65} outerRadius={95}>{categories.map((x,i)=><Cell key={x.name} fill={categoryColors[i%categoryColors.length]}/>)}</Pie><Tooltip formatter={v=>brl(Number(v))}/></PieChart></ResponsiveContainer></div><div>{categories.map((x,i)=><p key={x.name}><i style={{background:categoryColors[i%categoryColors.length]}}/><span>{x.name}</span><b>{brl(x.value)}</b></p>)}</div></div></section>}<section className="card report-table-card"><div className="section-title"><div><h3>Detalhamento — {view}</h3><p>{rows().length} registros encontrados</p></div></div><div className="report-table-wrap"><table><thead><tr>{headers().map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows().map((r,i)=><tr key={i}>{r.map((c,j)=><td key={j}>{c}</td>)}</tr>)}</tbody></table></div></section></div>
}
function AiPage({people}:{people:any}){
  const [msg,setMsg]=useState('');
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState('');
  const [chat,setChat]=useState<any[]>([{from:'ai',text:'Olá! Sou a Juntos IA. Posso analisar suas receitas, despesas, orçamento, metas e hábitos financeiros usando os dados cadastrados no aplicativo.'}]);
  const [financialData,setFinancialData]=useState<any>({transactions:[],budgets:[],cards:[],goals:[],subscriptions:[],shoppingLists:[]});
  useEffect(()=>{const read=(key:string)=>{try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return[]}};setFinancialData({transactions:read('juntos-transactions').slice(0,200),budgets:read('juntos-budgets'),cards:read('juntos-cards').map((card:any)=>({bank:card.bank,invoice:card.invoice,limit:card.limit,closing:card.closing,future:card.future})),goals:read('juntos-goals'),subscriptions:read('juntos-subscriptions'),shoppingLists:read('juntos-shopping-lists')})},[]);
  const send=async (suggestion?:string)=>{const text=(suggestion??msg).trim();if(!text||busy)return;const next=[...chat,{from:'user',text}];setChat(next);setMsg('');setError('');setBusy(true);try{const response=await fetch('/api/ai/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:next.filter(message=>message.from==='user'||message.from==='ai').slice(-12).map(message=>({role:message.from==='ai'?'assistant':'user',content:message.text})),financialData})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Não foi possível obter uma resposta.');setChat([...next,{from:'ai',text:data.answer}])}catch(reason){setError(reason instanceof Error?reason.message:'Não foi possível consultar a Juntos IA.')}finally{setBusy(false)}};
  const transactions=financialData.transactions||[];const income=transactions.filter((item:any)=>item.type==='in').reduce((sum:number,item:any)=>sum+Number(item.value||0),0);const expense=transactions.filter((item:any)=>item.type==='out').reduce((sum:number,item:any)=>sum+Number(item.value||0),0);
  return <div className="page-stack ai-page"><div className="page-heading"><div><p>Inteligência financeira</p><h1>Juntos IA <Sparkles size={25}/></h1><span>Decisões mais claras, feitas a dois.</span></div></div><div className="ai-layout"><section className="card chat"><div className="chat-head"><div className="ai-icon"><Sparkles/></div><div><b>Juntos IA, sua conselheira financeira</b><span><i/> {busy?'Analisando seus dados...':'Online'}</span></div></div><div className="messages">{chat.map((message,index)=><div className={`message ${message.from}`} key={index}>{message.text}</div>)}{busy&&<div className="message ai ai-thinking"><span/><span/><span/></div>}</div><div className="suggestions">{['Como estão meus gastos?','Onde posso economizar?','Resuma minhas finanças'].map(text=><button key={text} onClick={()=>send(text)} disabled={busy}>{text}</button>)}</div>{error&&<div className="ai-error">{error}</div>}<div className="chat-input"><input value={msg} onChange={event=>setMsg(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();send()}}} placeholder="Pergunte sobre suas finanças..." disabled={busy}/><button onClick={()=>send()} disabled={busy||!msg.trim()} aria-label="Enviar pergunta">{busy?<span className="ai-button-loader"/>:<ArrowUpRight/>}</button></div><small className="disclaimer">Respostas educativas baseadas nos dados cadastrados; não substituem orientação financeira profissional.</small></section><aside className="insights"><article className="card insight"><span>DADOS ANALISADOS</span><h3>{transactions.length} transações disponíveis</h3><p>Receitas: <b>{brl(income)}</b><br/>Despesas: <b>{brl(expense)}</b><br/>Resultado: <b>{brl(income-expense)}</b></p></article><article className="card insight opportunity"><span>COMO PERGUNTAR</span><h3>Seja específico</h3><p>Informe o período ou objetivo desejado. Exemplo: “Quanto gastei com mercado neste mês?”</p></article></aside></div></div>
}
function SettingsPage({dark,setDark,people,setPeople}:any){
  const {configured,workspace,members,refresh,user}=useAuth();
  const [tab,setTab]=useState('Perfil');
  const [editing,setEditing]=useState<'Rafael'|'Mariana'|null>(null);
  const [currency,setCurrency]=useState('BRL');
  const [prefs,setPrefs]=useState({email:true,push:true,bills:true,goals:true});
  const [categories,setCategories]=useState<string[]>(DEFAULT_TRANSACTION_CATEGORIES);
  const [newCategory,setNewCategory]=useState('');
  const [newPassword,setNewPassword]=useState('');
  const [passwordStatus,setPasswordStatus]=useState('');
  const [sharingMode,setSharingMode]=useState<'solo'|'shared'>('solo'); const [partnerEmail,setPartnerEmail]=useState(''); const [inviteStatus,setInviteStatus]=useState(''); const [inviteLink,setInviteLink]=useState('');
  useEffect(()=>{if(!user||!members.length)return;const current=members.find(member=>member.user_id===user.id);const partner=members.find(member=>member.user_id!==user.id);if(partner)setSharingMode('shared');setPeople((previous:any)=>({Rafael:{name:current?.profiles?.full_name||previous.Rafael.name,email:current?.profiles?.email||previous.Rafael.email},Mariana:partner?{name:partner.profiles?.full_name||previous.Mariana.name,email:partner.profiles?.email||previous.Mariana.email}:{name:'',email:''}}))},[user?.id,members]);
  useEffect(()=>{const saved=localStorage.getItem('juntos-settings');if(saved)try{const data=JSON.parse(saved);if(data.people)setPeople(data.people);if(data.currency)setCurrency(data.currency);if(data.prefs)setPrefs(data.prefs);if(Array.isArray(data.categories))setCategories([...new Set([...DEFAULT_TRANSACTION_CATEGORIES,...data.categories])]);if(data.sharingMode)setSharingMode(data.sharingMode);if(data.partnerEmail)setPartnerEmail(data.partnerEmail);if(data.inviteStatus)setInviteStatus(data.inviteStatus)}catch{}},[]);
  useEffect(()=>{const next=JSON.stringify({people,currency,prefs,categories,sharingMode,partnerEmail,inviteStatus});if(localStorage.getItem('juntos-settings')!==next)localStorage.setItem('juntos-settings',next)},[people,currency,prefs,categories,sharingMode,partnerEmail,inviteStatus]);
  const toggle=(key:keyof typeof prefs)=>setPrefs({...prefs,[key]:!prefs[key]});
  const changePassword=async()=>{if(newPassword.length<8){setPasswordStatus('A senha precisa ter pelo menos 8 caracteres.');return}setPasswordStatus('Atualizando senha...');const {error}=await createBrowserClient().auth.updateUser({password:newPassword});if(error){setPasswordStatus(error.message);return}setNewPassword('');setPasswordStatus('Senha alterada com sucesso.');appAction('Senha alterada com sucesso.')};
  const download=()=>{const blob=new Blob([JSON.stringify({people,currency,prefs,categories,sharingMode,partnerEmail,inviteStatus},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='juntos-finance-dados.json';a.click();URL.revokeObjectURL(url)};
  const install=async()=>{const event=(window as any).deferredInstallPrompt;if(event){await event.prompt()}else await alertDialog('No Chrome ou Edge, abra o menu do navegador e escolha “Instalar Juntos Finance”.')};
  const tabs=['Perfil','Preferências','Notificações','Privacidade e segurança','Categorias','Dados e exportação'];
  const resetSystem=async()=>{
    if(!workspace)return alertDialog('Não foi possível identificar seu espaço financeiro.');
    if(!await confirmDialog('ATENÇÃO: esta ação apagará todas as transações, cartões, metas, dívidas, assinaturas, listas, orçamentos e configurações do espaço em todos os aparelhos. A conta continuará ativa. Esta ação não pode ser desfeita.','Apagar todos os dados?'))return;
    const response=await fetch('/api/workspace/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({workspaceId:workspace.id})});
    const data=await response.json().catch(()=>({}));
    if(!response.ok)return alertDialog(data.error||'Não foi possível apagar os dados.');
    const activeWorkspace=localStorage.getItem('juntos-active-workspace');
    Object.keys(localStorage).forEach(key=>{if(key.startsWith('juntos-'))localStorage.removeItem(key)});
    if(activeWorkspace)localStorage.setItem('juntos-active-workspace',activeWorkspace);
    localStorage.setItem('juntos-sync-queue','{}');
    appAction('Todos os dados foram apagados. O aplicativo será recarregado.');
    setTimeout(()=>window.location.reload(),1200);
  };  const shareWhatsApp=()=>{if(!inviteLink)return;const message=`Convidei você para compartilhar nosso espaço no Juntos Finance. Abra este link usando o e-mail ${partnerEmail}: ${inviteLink} O convite é válido por 7 dias e cada pessoa usa sua própria senha.`;window.open(`https://wa.me/?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer')};
  const sendInvite=async()=>{
    if(!partnerEmail.includes('@'))return;
    if(!configured||!workspace){setInviteStatus('Configure o Supabase para enviar um convite real.');return}
    setInviteStatus('Enviando convite...');
    const response=await fetch('/api/invitations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:partnerEmail,workspaceId:workspace.id,role:'member'})});
    const data=await response.json();
    if(response.ok){setSharingMode('shared');setInviteLink(data.inviteUrl);setInviteStatus('Link seguro criado para '+partnerEmail+'. Válido por 7 dias.');appAction('Link de convite criado com sucesso.');await refresh()}else setInviteStatus(data.error||'Não foi possível enviar o convite.');
  };
  const partner=members.find(member=>member.user_id!==user?.id);
  const removePartner=async()=>{
    if(!workspace||!partner)return setSharingMode('solo');
    if(workspace.role!=='owner')return alertDialog('Somente o proprietário do espaço pode remover o cônjuge.');
    if(!await confirmDialog('Ao continuar, o cônjuge perderá o acesso a este espaço e aos dados compartilhados. A conta pessoal dele continuará ativa.','Remover cônjuge?'))return;
    const response=await fetch('/api/workspace/members',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({workspaceId:workspace.id,memberId:partner.user_id})});
    const data=await response.json().catch(()=>({}));if(!response.ok)return alertDialog(data.error||'Não foi possível remover o cônjuge.');
    setEditing(null);setSharingMode('solo');setPartnerEmail('');setInviteLink('');setInviteStatus('');setPeople({...people,Mariana:{name:'',email:''}});await refresh();appAction('Cônjuge removido. O espaço agora é individual.');
  };
  const chooseSharingMode=async(mode:'solo'|'shared')=>{if(mode==='solo'&&partner){await removePartner();return}setSharingMode(mode)};
  const saveSettingsProfile=async()=>{
    if(!editing)return;
    const name=people[editing].name.trim();if(!user||!name)return alertDialog('Informe o nome.');
    if(editing==='Mariana'){
      if(!workspace||!partner)return alertDialog('Cônjuge não encontrado.');
      const response=await fetch('/api/workspace/members',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({workspaceId:workspace.id,memberId:partner.user_id,name})});
      const data=await response.json().catch(()=>({}));if(!response.ok)return alertDialog(data.error||'Não foi possível editar o cônjuge.');
    }else{
      const supabase=createBrowserClient();const {error}=await supabase.from('profiles').update({full_name:name}).eq('id',user.id);if(error)return alertDialog('Não foi possível alterar o nome. Tente novamente.');
      const {error:metadataError}=await supabase.auth.updateUser({data:{full_name:name}});if(metadataError)return alertDialog('O nome foi salvo no perfil, mas não foi possível atualizar a conta.');
    }
    setEditing(null);await refresh();appAction('Nome atualizado com sucesso.');
  };
  const personCard=(key:'Rafael'|'Mariana',who:'R'|'M')=><div><Avatar who={who} label={people[key].name}/>{editing===key?<><input value={people[key].name} onChange={e=>setPeople({...people,[key]:{...people[key],name:e.target.value}})}/><small>{people[key].email}</small><button className="primary" onClick={saveSettingsProfile}>Salvar perfil</button><button className="ghost" onClick={()=>setEditing(null)}>Cancelar</button></>:<><b>{people[key].name}</b><small>{people[key].email}</small>{(key==='Rafael'||workspace?.role==='owner')&&<button className="ghost" onClick={()=>setEditing(key)}>Editar perfil</button>}{key==='Mariana'&&workspace?.role==='owner'&&<button className="ghost danger" onClick={removePartner}>Remover cônjuge</button>}</>}</div>;
  return <div className="page-stack"><div className="page-heading"><div><p>Seu espaço</p><h1>Configurações</h1><span>Personalize sua experiência.</span></div></div><div className="settings-layout"><aside className="card settings-nav">{tabs.map(x=><button className={tab===x?'active':''} onClick={()=>setTab(x)} key={x}>{x}<ChevronRight size={16}/></button>)}</aside><section className="card settings-content">
    {tab==='Perfil'&&<><h3>Meu perfil</h3><p>Use individualmente ou convide seu cônjuge.</p><div className="sharing-settings"><div className="sharing-choice"><button className={sharingMode==='solo'?'active':''} onClick={()=>void chooseSharingMode('solo')}><Users size={18}/><span><b>Somente eu</b><small>Controle financeiro individual</small></span></button><button className={sharingMode==='shared'?'active':''} onClick={()=>void chooseSharingMode('shared')}><Heart size={18}/><span><b>Compartilhar com cônjuge</b><small>Transforme o espaço em sistema de casal</small></span></button></div>{sharingMode==='shared'&&!partner&&<div className="partner-invite"><label>E-mail do cônjuge<input type="email" value={partnerEmail} onChange={e=>setPartnerEmail(e.target.value)} placeholder="conjuge@exemplo.com"/></label><button className="primary" onClick={sendInvite}>Gerar link seguro</button>{inviteLink&&<><button className="ghost" onClick={()=>{void navigator.clipboard.writeText(inviteLink);appAction('Link copiado.')}}>Copiar link</button><button className="ghost" onClick={shareWhatsApp}>Compartilhar pelo WhatsApp</button></>}{inviteStatus&&<div className="invite-status"><Check size={16}/><span>{inviteStatus}<small>A pessoa deve abrir o link com o e-mail informado e entrar ou criar sua conta.</small></span></div>}</div>}</div>
<div className="couple-edit">{personCard('Rafael','R')}{members.length>1&&<><Heart/>{personCard('Mariana','M')}</>}</div><hr/><div className="setting-row"><span><b>Tema escuro</b><small>Use a aparência que preferir</small></span><button className={`toggle ${dark?'on':''}`} onClick={()=>setDark(!dark)}><i/></button></div><div className="setting-row"><span><b>Moeda</b><small>Formato usado em todo o app</small></span><select className="settings-select" value={currency} onChange={e=>setCurrency(e.target.value)}><option value="BRL">Real brasileiro (BRL)</option><option value="USD">Dólar (USD)</option><option value="EUR">Euro (EUR)</option></select></div><div className="setting-row"><span><b>Instalar aplicativo</b><small>Acesse o Juntos Finance pela tela inicial</small></span><button className="primary" onClick={install}><Download size={17}/> Instalar</button></div></>}
    {tab==='Preferências'&&<><h3>Preferências</h3><p>Escolha como o aplicativo deve se comportar.</p><div className="setting-row"><span><b>Tema escuro</b><small>Alternar aparência do aplicativo</small></span><button className={`toggle ${dark?'on':''}`} onClick={()=>setDark(!dark)}><i/></button></div><div className="setting-row"><span><b>Moeda principal</b><small>Usada em saldos e relatórios</small></span><select className="settings-select" value={currency} onChange={e=>setCurrency(e.target.value)}><option value="BRL">Real brasileiro (BRL)</option><option value="USD">Dólar (USD)</option><option value="EUR">Euro (EUR)</option></select></div></>}
    {tab==='Notificações'&&<><h3>Notificações</h3><p>Controle os avisos que deseja receber.</p>{([['email','Notificações por e-mail'],['push','Notificações no navegador'],['bills','Lembretes de contas'],['goals','Atualizações de metas']] as const).map(([key,label])=><div className="setting-row" key={key}><span><b>{label}</b><small>Você pode alterar quando quiser</small></span><button className={`toggle ${prefs[key]?'on':''}`} onClick={()=>toggle(key)}><i/></button></div>)}</>}
    {tab==='Privacidade e segurança'&&<><h3>Privacidade e segurança</h3><p>Proteja seus dados financeiros.</p><div className="setting-row"><span><b>Alterar senha</b><small>Use no mínimo 8 caracteres</small></span><div className="category-add"><input type="password" value={newPassword} onChange={e=>setNewPassword(e.target.value)} placeholder="Nova senha" autoComplete="new-password"/><button className="primary" onClick={changePassword} disabled={!configured}>Alterar senha</button></div></div>{passwordStatus&&<p className="invite-status">{passwordStatus}</p>}{!configured&&<p>Configure o Supabase para habilitar a alteração de senha.</p>}</>}
    {tab==='Categorias'&&<><h3>Categorias</h3><p>Organize as classificações das movimentações.</p><div className="category-list">{categories.map(x=><div key={x}><span>{x}</span><button onClick={()=>setCategories(categories.filter(c=>c!==x))}><X size={16}/></button></div>)}</div><div className="category-add"><input value={newCategory} onChange={e=>setNewCategory(e.target.value)} placeholder="Nova categoria"/><button className="primary" onClick={()=>{if(newCategory.trim()){setCategories([...categories,newCategory.trim()]);setNewCategory('')}}}><Plus size={16}/> Adicionar</button></div></>}
    {tab==='Dados e exportação'&&<><h3>Dados e exportação</h3><p>Baixe uma cópia ou apague todo o conteúdo do espaço.</p><div className="setting-row"><span><b>Exportar meus dados</b><small>Arquivo JSON compatível com backup</small></span><button className="primary" onClick={download}><Download size={17}/> Exportar dados</button></div><div className="setting-row"><span><b>Apagar todos os dados</b><small>Exclui definitivamente os dados financeiros e configurações em todos os aparelhos</small></span><button className="ghost danger" onClick={resetSystem}>Restaurar e apagar tudo</button></div></>}
  </section></div></div>
}

function OrganizerPage({title}:{title:string}){
  const key='juntos-organizer-'+title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,'-');
  const presets:any={};
  const [items,setItems]=useState<any[]>(presets[title]||[]); const [editing,setEditing]=useState<any>(null); const [query,setQuery]=useState('');
  useEffect(()=>{const saved=localStorage.getItem(key);if(saved)try{setItems(JSON.parse(saved))}catch{}},[key]);
  const persist=(next:any[])=>{setItems(next);localStorage.setItem(key,JSON.stringify(next))};
  const openNew=()=>setEditing({id:Date.now(),name:'',value:'',date:new Intl.DateTimeFormat('en-CA').format(new Date()),status:'Planejado',notes:'',isNew:true});
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,value:Number(String(editing.value).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction('Alterações salvas com sucesso.')};
  const remove=async()=>{if(await confirmDialog('Deseja excluir este registro?')){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Registro excluído.')}};
  const filtered=items.filter(x=>x.name.toLowerCase().includes(query.toLowerCase())); const total=items.reduce((sum,x)=>sum+Number(x.value||0),0);
  return <div className="page-stack organizer-page"><div className="page-heading"><div><p>Organização financeira</p><h1>{title}</h1><span>Cadastre, acompanhe e atualize tudo quando quiser.</span></div><button className="primary" onClick={openNew}><Plus size={17}/> Novo registro</button></div><div className="metrics-grid compact"><MetricCard label="Total planejado" value={brl(total)} detail={`${items.length} registros`} icon={WalletCards} tone="purple"/><MetricCard label="Pendentes" value={String(items.filter(x=>x.status==='Pendente').length)} detail="Precisam de atenção" icon={CalendarDays} tone="warning"/><MetricCard label="Concluídos" value={String(items.filter(x=>x.status==='Concluído').length)} detail="Neste período" icon={Check} tone="positive"/></div><section className="card organizer-list"><label className="search"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={`Buscar em ${title.toLowerCase()}...`}/></label>{filtered.length?filtered.map(x=><button className="organizer-row" key={x.id} onClick={()=>setEditing({...x})}><span className="organizer-row-icon"><ReceiptText size={17}/></span><span><b>{x.name}</b><small>{x.notes||'Sem observações'}</small></span><time>{new Date(x.date+'T12:00:00').toLocaleDateString('pt-BR')}</time><i>{x.status}</i><strong>{brl(Number(x.value))}</strong><ChevronRight size={17}/></button>):<div className="organizer-empty">Nenhum registro encontrado.</div>}</section>{editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal organizer-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO REGISTRO':'EDITAR REGISTRO'}</span><h2>{editing.isNew?`Adicionar em ${title}`:'Atualizar informações'}</h2><p>Todos os campos podem ser alterados depois.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="organizer-edit-grid"><label className="field-full">Nome<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} required placeholder="Digite um nome"/></label><label>Valor (R$)<input value={editing.value} onChange={e=>setEditing({...editing,value:e.target.value.replace(/[^0-9,.]/g,'')})} required inputMode="decimal"/></label><label>Data<input type="date" value={editing.date} onChange={e=>setEditing({...editing,date:e.target.value})} required/></label><label>Status<select value={editing.status} onChange={e=>setEditing({...editing,status:e.target.value})}><option>Planejado</option><option>Pendente</option><option>Em andamento</option><option>Concluído</option><option>Cancelado</option></select></label><label className="field-full">Observações<textarea rows={3} value={editing.notes} onChange={e=>setEditing({...editing,notes:e.target.value})} placeholder="Detalhes opcionais"/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar</button></div></form></div>}</div>
}
function Placeholder({title,onGo}:{title:string,onGo:()=>void}){return <div className="empty-page"><div className="empty-illustration"><Heart/><Sparkles/></div><p>Juntos Finance</p><h1>{title}</h1><span>Este espaço já faz parte da experiência e está pronto para receber seus próximos dados.</span><button className="primary" onClick={onGo}>Voltar ao dashboard</button></div>}

function ShoppingPage({onFinish}:{onFinish:(data:any)=>void}){
  const storageKey='juntos-shopping-lists';
  const [lists,setLists]=useState<any[]>([]);
  const [selectedId,setSelectedId]=useState('');
  const [listName,setListName]=useState<string|null>(null);
  const [item,setItem]=useState({name:'',quantity:'1',price:'',category:'Mercado'});
  const [checkout,setCheckout]=useState<any|null>(null);
  const [cards,setCards]=useState<any[]>([]);
  useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');setLists(saved);setSelectedId(saved[0]?.id||'')}catch{}try{setCards(JSON.parse(localStorage.getItem('juntos-cards')||'[]'))}catch{}},[]);
  const persist=(next:any[])=>{setLists(next);localStorage.setItem(storageKey,JSON.stringify(next))};
  const selected=lists.find(list=>list.id===selectedId)||lists[0];
  const createList=(e:React.FormEvent)=>{e.preventDefault();if(!listName?.trim())return;const next={id:'list-'+Date.now(),name:listName.trim(),items:[],createdAt:new Intl.DateTimeFormat('en-CA').format(new Date())};persist([...lists,next]);setSelectedId(next.id);setListName(null)};
  const addItem=(e:React.FormEvent)=>{e.preventDefault();if(!selected||!item.name.trim())return;const price=Number(item.price.replace(/[.]/g,'').replace(',','.'));const quantity=Math.max(1,Number(item.quantity)||1);const next=lists.map(list=>list.id===selected.id?{...list,finalizedAt:null,items:[...list.items,{id:Date.now(),name:item.name.trim(),quantity,price:Number.isFinite(price)?price:0,category:item.category,bought:false}]}:list);persist(next);setItem({name:'',quantity:'1',price:'',category:'Mercado'})};
  const toggleItem=(id:number)=>persist(lists.map(list=>list.id===selected.id?{...list,finalizedAt:null,items:list.items.map((entry:any)=>entry.id===id?{...entry,bought:!entry.bought}:entry)}:list));
  const removeItem=(id:number)=>persist(lists.map(list=>list.id===selected.id?{...list,finalizedAt:null,items:list.items.filter((entry:any)=>entry.id!==id)}:list));
  const removeList=async()=>{if(!selected||!await confirmDialog(`Excluir a lista “${selected.name}”?`))return;const next=lists.filter(list=>list.id!==selected.id);persist(next);setSelectedId(next[0]?.id||'')};
  const total=selected?.items.reduce((sum:number,entry:any)=>sum+entry.quantity*entry.price,0)||0;
  const bought=selected?.items.filter((entry:any)=>entry.bought).reduce((sum:number,entry:any)=>sum+entry.quantity*entry.price,0)||0;
  const finish=(e:React.FormEvent)=>{e.preventDefault();if(!selected||bought<=0)return;onFinish({title:`Compras - ${selected.name}`,category:'Mercado',person:'Casal',account:'Carteira',payment:checkout.payment,card:checkout.card,date:checkout.date,value:bought,type:'out',icon:'−'});persist(lists.map(list=>list.id===selected.id?{...list,finalizedAt:checkout.date}:list));setCheckout(null)};
  const openCheckout=()=>setCheckout({date:new Intl.DateTimeFormat('en-CA').format(new Date()),payment:'Pix',card:''});
  return <div className="page-stack shopping-page"><div className="page-heading"><div><p>Planejamento de compras</p><h1>App de compras</h1><span>Planeje, compartilhe e transforme sua lista em despesa.</span></div><button className="primary" onClick={()=>setListName('')}><Plus size={17}/> Nova lista</button></div>
    {lists.length>0&&<div className="shopping-tabs">{lists.map(list=><button className={list.id===selected?.id?'active':''} onClick={()=>setSelectedId(list.id)} key={list.id}>{list.name}</button>)}</div>}
    {!selected?<section className="card shopping-empty"><Search size={30}/><h2>Crie sua primeira lista</h2><p>Organize supermercado, farmácia, material escolar e outras compras.</p><button className="primary" onClick={()=>setListName('')}><Plus size={17}/> Criar lista</button></section>:<>
      <div className="metrics-grid compact"><MetricCard label="Total previsto" value={brl(total)} detail={`${selected.items.length} produtos`} icon={WalletCards} tone="purple"/><MetricCard label="Já comprado" value={brl(bought)} detail={`${selected.items.filter((x:any)=>x.bought).length} concluídos`} icon={Check} tone="positive"/><MetricCard label="Restante" value={brl(Math.max(0,total-bought))} detail="Itens pendentes" icon={ReceiptText} tone="warning"/></div>
      <section className="card shopping-card"><div className="section-title"><div><h3>{selected.name}</h3><p>{selected.finalizedAt?`Registrada em ${new Date(selected.finalizedAt+'T12:00:00').toLocaleDateString('pt-BR')}`:'Marque os itens conforme comprar'}</p></div><button className="ghost danger" onClick={removeList}>Excluir lista</button></div>
        <form className="shopping-add" onSubmit={addItem}><input value={item.name} onChange={e=>setItem({...item,name:e.target.value})} placeholder="Nome do produto" required/><input value={item.quantity} onChange={e=>setItem({...item,quantity:e.target.value.replace(/\D/g,'')})} placeholder="Qtd." inputMode="numeric"/><input value={item.price} onChange={e=>setItem({...item,price:e.target.value.replace(/[^0-9,.]/g,'')})} placeholder="Preço unitário" inputMode="decimal"/><select value={item.category} onChange={e=>setItem({...item,category:e.target.value})}>{['Mercado','Farmácia','Casa','Higiene','Educação','Outros'].map(x=><option key={x}>{x}</option>)}</select><button className="primary"><Plus size={17}/> Adicionar</button></form>
        <div className="shopping-list">{selected.items.length?selected.items.map((entry:any)=><div className={`shopping-item ${entry.bought?'bought':''}`} key={entry.id}><button className="shopping-check" onClick={()=>toggleItem(entry.id)} aria-label={entry.bought?'Marcar como pendente':'Marcar como comprado'}>{entry.bought&&<Check size={16}/>}</button><span><b>{entry.name}</b><small>{entry.category} · {entry.quantity} {entry.quantity===1?'unidade':'unidades'}</small></span><strong>{brl(entry.quantity*entry.price)}</strong><button className="shopping-remove" onClick={()=>removeItem(entry.id)} aria-label="Excluir produto"><X size={16}/></button></div>):<div className="organizer-empty">Nenhum produto adicionado.</div>}</div>
        <div className="shopping-footer"><span><small>Total da lista</small><b>{brl(total)}</b></span><button className="primary" onClick={openCheckout} disabled={bought<=0||Boolean(selected.finalizedAt)}>{selected.finalizedAt?'Compra registrada':'Finalizar compra'}</button></div>
      </section>
    </>}
    {listName!==null&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setListName(null)}><form className="modal shopping-list-modal" onSubmit={createList}><div className="edit-modal-head"><div><span>NOVA LISTA</span><h2>Criar lista de compras</h2><p>Dê um nome fácil de identificar.</p></div><button type="button" className="icon-button" onClick={()=>setListName(null)}><X/></button></div><label>Nome da lista<input value={listName} onChange={e=>setListName(e.target.value)} placeholder="Ex.: Compras do mês" autoFocus required/></label><div className="edit-modal-actions"><span/><button type="button" className="ghost" onClick={()=>setListName(null)}>Cancelar</button><button className="primary">Criar lista</button></div></form></div>}
    {checkout&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setCheckout(null)}><form className="modal shopping-checkout" onSubmit={finish}><div className="edit-modal-head"><div><span>FINALIZAR COMPRA</span><h2>{selected?.name}</h2><p>Será criada uma despesa de {brl(bought)}.</p></div><button type="button" className="icon-button" onClick={()=>setCheckout(null)}><X/></button></div><div className="shopping-checkout-grid"><label>Data<input type="date" value={checkout.date} onChange={e=>setCheckout({...checkout,date:e.target.value})} required/></label><label>Forma de pagamento<select value={checkout.payment} onChange={e=>setCheckout({...checkout,payment:e.target.value})}>{['Pix','Débito','Crédito','Dinheiro','Boleto','Transferência'].map(x=><option key={x}>{x}</option>)}</select></label>{cards.length>0&&<label className="field-full">Cartão (opcional)<select value={checkout.card} onChange={e=>setCheckout({...checkout,card:e.target.value})}><option value="">Nenhum</option>{cards.map(card=>{const label=card.last4?`${card.bank} final ${card.last4}`:card.bank;return <option value={label} key={card.id}>{label}</option>})}</select></label>}</div><div className="edit-modal-actions"><span/><button type="button" className="ghost" onClick={()=>setCheckout(null)}>Cancelar</button><button className="primary"><Check size={17}/> Registrar despesa</button></div></form></div>}
  </div>
}
function DebtsPage(){
  const [items,setItems]=useState<any[]>([]);const [editing,setEditing]=useState<any|null>(null);
  useEffect(()=>{try{setItems(JSON.parse(localStorage.getItem('juntos-debts')||'[]'))}catch{}},[]);
  const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-debts',JSON.stringify(next));window.dispatchEvent(new Event('juntos-debts-updated'))};
  const openNew=()=>setEditing({id:Date.now(),name:'',creditor:'',total:'',paid:'0',due:new Intl.DateTimeFormat('en-CA').format(new Date()),interest:'0',isNew:true});
  const save=(event:React.FormEvent)=>{event.preventDefault();const item={...editing,total:Number(String(editing.total).replace(/[.]/g,'').replace(',','.')),paid:Number(String(editing.paid).replace(/[.]/g,'').replace(',','.')),interest:Number(String(editing.interest).replace(',','.'))};delete item.isNew;if(!item.name.trim()||item.total<=0)return;persist(editing.isNew?[...items,item]:items.map(entry=>entry.id===item.id?item:entry));setEditing(null);appAction(editing.isNew?'Dívida cadastrada.':'Dívida atualizada.')};
  const remove=async()=>{if(editing&&!editing.isNew&&await confirmDialog(`Excluir a dívida “${editing.name}”?`)){persist(items.filter(item=>item.id!==editing.id));setEditing(null)}};
  const total=items.reduce((sum,item)=>sum+Math.max(0,Number(item.total)-Number(item.paid)),0);const paid=items.reduce((sum,item)=>sum+Number(item.paid||0),0);const nextDue=[...items].filter(item=>Number(item.paid)<Number(item.total)).sort((a,b)=>a.due.localeCompare(b.due))[0];
  return <div className="page-stack"><div className="page-heading"><div><p>Planejamento financeiro</p><h1>Controle de dívidas</h1><span>Acompanhe saldo, juros, vencimentos e pagamentos.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Nova dívida</button></div><div className="metrics-grid compact"><MetricCard label="Saldo devedor" value={brl(total)} detail={`${items.length} dívidas cadastradas`} icon={Landmark} tone="negative"/><MetricCard label="Total pago" value={brl(paid)} detail="Valor amortizado" icon={Check} tone="positive"/><MetricCard label="Próximo vencimento" value={nextDue?new Date(nextDue.due+'T12:00:00').toLocaleDateString('pt-BR'):'—'} detail={nextDue?.name||'Nenhuma pendência'} icon={CalendarDays} tone="warning"/></div><section className="card organizer-list">{items.length?items.map(item=>{const remaining=Math.max(0,item.total-item.paid);const pct=Math.min(100,Math.round(item.paid/item.total*100)||0);return <button className="organizer-row" onClick={()=>setEditing({...item,total:String(item.total).replace('.',','),paid:String(item.paid).replace('.',','),interest:String(item.interest).replace('.',',')})} key={item.id}><span className="organizer-row-icon"><Landmark size={17}/></span><span><b>{item.name}</b><small>{item.creditor} · {item.interest}% ao mês · {pct}% pago</small></span><time>{new Date(item.due+'T12:00:00').toLocaleDateString('pt-BR')}</time><i>{remaining<=0?'Quitada':'Em aberto'}</i><strong>{brl(remaining)}</strong><ChevronRight size={17}/></button>}):<div className="organizer-empty">Nenhuma dívida cadastrada.</div>}</section>{editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal organizer-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVA DÍVIDA':'EDITAR DÍVIDA'}</span><h2>{editing.isNew?'Cadastrar dívida':editing.name}</h2><p>Informe os valores para acompanhar a quitação.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="organizer-edit-grid"><label className="field-full">Descrição<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} placeholder="Ex.: Financiamento" required/></label><label>Credor<input value={editing.creditor} onChange={e=>setEditing({...editing,creditor:e.target.value})} placeholder="Banco ou pessoa"/></label><label>Vencimento<input type="date" value={editing.due} onChange={e=>setEditing({...editing,due:e.target.value})} required/></label><label>Valor total<input value={editing.total} onChange={e=>setEditing({...editing,total:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal" required/></label><label>Valor já pago<input value={editing.paid} onChange={e=>setEditing({...editing,paid:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal"/></label><label>Juros ao mês (%)<input value={editing.interest} onChange={e=>setEditing({...editing,interest:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal"/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar dívida</button></div></form></div>}</div>
}
function TransactionModal({close,success,people,isCouple}:any){
  const [type,setType]=useState('Despesa');
  const [availableCards,setAvailableCards]=useState<any[]>([]);
  const [availableAccounts,setAvailableAccounts]=useState<any[]>([]);
  const [categories,setCategories]=useState<string[]>(DEFAULT_TRANSACTION_CATEGORIES);
  useEffect(()=>{try{setAvailableCards(JSON.parse(localStorage.getItem('juntos-cards')||'[]'))}catch{setAvailableCards([])}try{setAvailableAccounts(JSON.parse(localStorage.getItem('juntos-accounts')||'[]'))}catch{setAvailableAccounts([])}try{const configured=JSON.parse(localStorage.getItem('juntos-settings')||'{}').categories;if(Array.isArray(configured))setCategories([...new Set([...DEFAULT_TRANSACTION_CATEGORIES,...configured])])}catch{}},[]);
  const [form,setForm]=useState(()=>({description:'',value:'',date:new Intl.DateTimeFormat('en-CA').format(new Date()),category:'',person:'Rafael',account:'',payment:'',card:'',notes:'',recurring:false,installments:1}));
  const set=(key:string,value:any)=>setForm({...form,[key]:value});
  const submit=(e:any)=>{e.preventDefault();if(!form.description||!form.value||!form.category||!form.account||!form.payment)return;const parsed=Number(form.value.replace(/[.]/g,'').replace(',','.'));success({...form,title:form.description,value:parsed,type:type==='Receita'?'in':'out',icon:type==='Receita'?'↗':'−'});close()};
  return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><form className="modal transaction-modal" onSubmit={submit}>
    <div className="transaction-modal-head"><div><h2>Nova transação</h2><p>Registre suas receitas, despesas ou transferências.</p></div><button type="button" onClick={close} aria-label="Fechar"><X size={19}/></button></div>
    <div className="type-switch transaction-types">{['Receita','Despesa','Transferência'].map(x=><button type="button" className={type===x?'active':''} onClick={()=>setType(x)} key={x}>{x}</button>)}</div>
    <div className="transaction-form">
      <label className="field-full">Descrição<input value={form.description} onChange={e=>set('description',e.target.value)} placeholder="Ex: Mercado do mês" required/></label>
      <label>Valor (R$)<input value={form.value} onChange={e=>set('value',e.target.value.replace(/[^0-9,.]/g,''))} placeholder="0,00" inputMode="decimal" required/></label>
      <label>Data<input type="date" value={form.date} onChange={e=>set('date',e.target.value)} required/></label>
      <label>Categoria<select value={form.category} onChange={e=>set('category',e.target.value)} required><option value="">Selecione</option>{categories.map(x=><option key={x}>{x}</option>)}</select></label>
      <label>Pessoa<select value={form.person} onChange={e=>set('person',e.target.value)}><option value="Rafael">Você</option><option value="Mariana">Parceiro(a)</option><option>Casal</option></select></label>
      <label>Conta<select value={form.account} onChange={e=>set('account',e.target.value)} required><option value="">Selecione</option><option>Carteira</option>{availableAccounts.map(account=><option value={account.name} key={account.id}>{account.name} · {account.bank}</option>)}</select></label>
      <label>Forma de pagamento<select value={form.payment} onChange={e=>set('payment',e.target.value)} required><option value="">Selecione</option>{['Pix','Débito','Crédito','Dinheiro','Boleto','Transferência'].map(x=><option key={x}>{x}</option>)}</select></label>
      {availableCards.length>0&&<label>Cartão (opcional)<select value={form.card} onChange={e=>set('card',e.target.value)}><option value="">Nenhum</option>{availableCards.map(card=>{const label=card.last4?`${card.bank} final ${card.last4}`:card.bank;return <option value={label} key={card.id}>{label}</option>})}</select></label>}

      <label className="field-full">Observação<textarea value={form.notes} onChange={e=>set('notes',e.target.value)} placeholder="Detalhes opcionais" rows={3}/></label>
      {type==='Despesa'&&form.payment==='Crédito'&&<label className="field-full">Parcelamento<select value={form.installments} onChange={e=>set('installments',Number(e.target.value))}>{Array.from({length:24},(_,index)=>index+1).map(number=><option value={number} key={number}>{number===1?'À vista':number+' parcelas'}</option>)}</select></label>}
      <div className="recurring-row field-full"><span><b>Transação recorrente</b><small>Gerar automaticamente os próximos 12 meses</small></span><button type="button" className={`toggle ${form.recurring?'on':''}`} onClick={()=>set('recurring',!form.recurring)}><i/></button></div>
    </div>
    <div className="transaction-modal-actions"><button type="button" className="ghost" onClick={close}>Cancelar</button><button className="primary">Salvar transação</button></div>
  </form></div>
}

function FinanceApp(){
  const {user,workspace,members,signOut,refresh}=useAuth();
  const isCouple=members.length>1;
  const loggedName=(members.find(m=>m.user_id===user?.id)?.profiles?.full_name||user?.user_metadata?.full_name||'') as string;
  const [active,setActive]=useState("Dashboard"); const [mobileMenu,setMobileMenu]=useState(false); const [modal,setModal]=useState(false); const [toast,setToast]=useState(false); const [hidden,setHidden]=useState(false); const [dark,setDark]=useState(true); const [themeReady,setThemeReady]=useState(false);
  const [storageReady,setStorageReady]=useState(false);
  const [actionToast,setActionToast]=useState('');
  const [dialog,setDialog]=useState<any|null>(null);
  const [people,setPeople]=useState({Rafael:{name:'',email:''},Mariana:{name:'',email:''}});
  const [balances,setBalances]=useState({couple:0,rafael:0,mariana:0,investments:0});
  const [notificationsOpen,setNotificationsOpen]=useState(false); const [profileOpen,setProfileOpen]=useState(false);
  const [spaceOpen,setSpaceOpen]=useState(false); const [space,setSpace]=useState({name:'',description:'Nosso espaço financeiro'});
  const [notifications,setNotifications]=useState<any[]>([]);
  const [syncState,setSyncState]=useState<{status:string;error?:string}>({status:'synced'});
  useEffect(()=>{const status=(event:Event)=>setSyncState((event as CustomEvent).detail);window.addEventListener('juntos-sync-status',status);return()=>window.removeEventListener('juntos-sync-status',status)},[]);
  useEffect(()=>{const loadAlerts=()=>{const today=new Intl.DateTimeFormat('en-CA').format(new Date());const limitDate=new Date();limitDate.setDate(limitDate.getDate()+7);const limit=new Intl.DateTimeFormat('en-CA').format(limitDate);let events:any[]=[],tx:any[]=[],debts:any[]=[],subscriptions:any[]=[];try{events=JSON.parse(localStorage.getItem('juntos-calendar-events')||'[]');tx=JSON.parse(localStorage.getItem('juntos-transactions')||'[]');debts=JSON.parse(localStorage.getItem('juntos-debts')||'[]');subscriptions=JSON.parse(localStorage.getItem('juntos-subscriptions')||'[]')}catch{}const alerts=[...events.filter(item=>item.date>=today&&item.date<=limit).map(item=>({id:'event-'+item.id,title:'Vencimento próximo',text:`${item.title} vence em ${new Date(item.date+'T12:00:00').toLocaleDateString('pt-BR')}`,time:'Calendário',read:false})),...tx.filter(item=>item.type==='out'&&item.dateInput>today&&item.dateInput<=limit).map(item=>({id:'tx-'+item.id,title:item.installments>1?'Parcela próxima':'Pagamento previsto',text:`${item.title}: ${brl(Number(item.value))}`,time:new Date(item.dateInput+'T12:00:00').toLocaleDateString('pt-BR'),read:false})),...debts.filter(item=>Number(item.paid)<Number(item.total)&&item.due>=today&&item.due<=limit).map(item=>({id:'debt-'+item.id,title:'Dívida próxima do vencimento',text:`${item.name}: faltam ${brl(Number(item.total)-Number(item.paid))}`,time:new Date(item.due+'T12:00:00').toLocaleDateString('pt-BR'),read:false})),...subscriptions.filter(item=>item.active&&item.next>=today&&item.next<=limit).map(item=>({id:'sub-'+item.id,title:'Assinatura próxima',text:`${item.name}: ${brl(Number(item.value))}`,time:new Date(item.next+'T12:00:00').toLocaleDateString('pt-BR'),read:false}))];setNotifications(previous=>alerts.map(alert=>({...alert,read:previous.find(item=>item.id===alert.id)?.read||false})))};loadAlerts();const names=['juntos-transactions-updated','juntos-calendar-updated','juntos-debts-updated','juntos-cloud-synced'];names.forEach(name=>window.addEventListener(name,loadAlerts));return()=>names.forEach(name=>window.removeEventListener(name,loadAlerts))},[]);
  useEffect(()=>{setStorageReady(true)},[]);
  useEffect(()=>{const saved=localStorage.getItem('juntos-theme');setDark(saved!=='light');setThemeReady(true)},[]);useEffect(()=>{if(!themeReady)return;document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('juntos-theme',dark?'dark':'light')},[dark,themeReady]);
  useEffect(()=>{if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(()=>undefined)},[]);
  useEffect(()=>{const savedSpace=localStorage.getItem('juntos-space');if(savedSpace)try{setSpace(JSON.parse(savedSpace))}catch{}},[]);
  useEffect(()=>{const saved=localStorage.getItem('juntos-settings');if(saved)try{const data=JSON.parse(saved);if(data.people)setPeople(data.people)}catch{}},[]);
  useEffect(()=>{const saved=localStorage.getItem('juntos-balances');if(saved)try{setBalances({...balances,...JSON.parse(saved)})}catch{}},[]);
  useEffect(()=>{const handler=(event:Event)=>{const detail=(event as CustomEvent<string|{page:string}>).detail;if(typeof detail==='string'){setActionToast(detail);setToast(true);setTimeout(()=>setToast(false),2600)}else if(detail?.page){setActive(detail.page);window.scrollTo({top:0,behavior:'smooth'})}};window.addEventListener('juntos-action',handler);return()=>window.removeEventListener('juntos-action',handler)},[]);
  useEffect(()=>{const handler=(event:Event)=>setDialog((event as CustomEvent).detail);window.addEventListener('juntos-dialog',handler);return()=>window.removeEventListener('juntos-dialog',handler)},[]);
  useEffect(()=>{if(!dialog)return;const keyHandler=(event:KeyboardEvent)=>{if(event.key==='Escape'&&!dialog.alert){dialog.resolve(false);setDialog(null)}};window.addEventListener('keydown',keyHandler);return()=>window.removeEventListener('keydown',keyHandler)},[dialog]);
  const closeDialog=(result:boolean)=>{dialog?.resolve(result);setDialog(null)};
  const saveProfile=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const name=people.Rafael.name.trim();if(!user||!name)return;const supabase=createBrowserClient();const {error}=await supabase.from('profiles').update({full_name:name}).eq('id',user.id);if(error){await alertDialog('Não foi possível alterar o nome. Tente novamente.');return}const {error:metadataError}=await supabase.auth.updateUser({data:{full_name:name}});if(metadataError){await alertDialog('O nome foi salvo no perfil, mas não foi possível atualizar a conta.');return}const current=JSON.parse(localStorage.getItem('juntos-settings')||'{}');localStorage.setItem('juntos-settings',JSON.stringify({...current,people:{...people,Rafael:{...people.Rafael,name}}}));await refresh();setProfileOpen(false);setActionToast('Nome atualizado com sucesso.');setToast(true);setTimeout(()=>setToast(false),3000)};
  const saveTransaction=(data:any)=>{const saved=localStorage.getItem('juntos-transactions');const current=saved?JSON.parse(saved):transactions;const count=data.recurring?12:Math.max(1,Number(data.installments)||1);const seriesId=Date.now();const addMonths=(input:string,amount:number)=>{const [year,month,day]=input.split('-').map(Number);const target=new Date(year,month-1+amount,1);const safeDay=Math.min(day,new Date(target.getFullYear(),target.getMonth()+1,0).getDate());return target.getFullYear()+'-'+String(target.getMonth()+1).padStart(2,'0')+'-'+String(safeDay).padStart(2,'0')};const generated=Array.from({length:count},(_,index)=>{const dateInput=addMonths(data.date,index);const date=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(dateInput+'T12:00:00')).replace('.','');const installment=count>1&&!data.recurring;return {id:seriesId+index,title:installment?data.title+' ('+(index+1)+'/'+count+')':data.title,category:data.category,person:data.person,account:data.account,payment:data.payment,card:data.card,date,dateInput,value:installment?Number((data.value/count).toFixed(2)):data.value,type:data.type,icon:data.icon,seriesId,recurring:Boolean(data.recurring),installment:index+1,installments:count}});const next=[...generated,...current].sort((a,b)=>(b.dateInput||'').localeCompare(a.dateInput||''));localStorage.setItem('juntos-transactions',JSON.stringify(next));const accountKey=data.account==='Conta Rafael'?'rafael':data.account==='Conta Mariana'?'mariana':data.account==='Conta do casal'?'couple':null;if(accountKey){setBalances(previous=>{const updated={...previous,[accountKey]:Math.max(0,Number(previous[accountKey as keyof typeof previous]||0)+(data.type==='in'?data.value:-data.value))};localStorage.setItem('juntos-balances',JSON.stringify(updated));return updated})}window.dispatchEvent(new Event('juntos-transactions-updated'));setActionToast(data.recurring?'Recorrência criada para 12 meses.':Number(data.installments)>1?'Compra parcelada com sucesso.':data.category==='Salário'&&data.type==='in'?'Salário adicionado ao seu saldo!':'Transação adicionada com sucesso!');setToast(true);setTimeout(()=>setToast(false),3000)};
  const unread=notifications.filter(n=>!n.read).length;
  const content=useMemo(()=>{const p:any={Dashboard:<Dashboard onNew={()=>setModal(true)} onAi={()=>setActive('IA Conselheira')} hidden={hidden} people={people} currentName={loggedName}/>,"Transações":<TransactionsPage onNew={()=>setModal(true)} people={people} isCouple={isCouple}/>,"Orçamentos":<BudgetsPage/>,"Cartões":<CardsPage people={people}/>,"Calendário":<CalendarPage people={people}/>,Metas:<GoalsPage/>,"Dívidas":<DebtsPage/>,Assinaturas:<SubscriptionsPage/>,"App de compras":<ShoppingPage onFinish={saveTransaction}/>,"Relatórios":<ReportsPage people={people}/>,"IA Conselheira":<AiPage people={people}/>,"Configurações":<SettingsPage dark={dark} setDark={setDark} people={people} setPeople={setPeople}/>};return p[active]||<Placeholder title={active} onGo={()=>setActive('Dashboard')}/>},[active,hidden,dark,people,balances,isCouple,loggedName]);
  const navigate=(x:string)=>{setActive(x);setMobileMenu(false);window.scrollTo({top:0,behavior:'smooth'})};
  if(!storageReady)return <div className="app-shell"><div className="main-shell"><main /></div></div>;
  return <div className="app-shell">
    <aside className={`sidebar ${mobileMenu?'open':''}`}><div className="sidebar-top"><Logo/><button className="mobile-close icon-button" onClick={()=>setMobileMenu(false)}><X/></button></div><nav><span>MENU PRINCIPAL</span>{menu.map(([label,Icon])=><button key={label} onClick={()=>navigate(label)} className={active===label?'active':''}><Icon size={18}/><span>{label}</span>{label==='IA Conselheira'&&<i>Novo</i>}</button>)}</nav><div className="sidebar-bottom"><button onClick={()=>navigate('Configurações')} className={active==='Configurações'?'active':''}><Settings size={18}/>Configurações</button></div></aside>
    <CloudSync/><div className="main-shell"><header className="topbar"><button className="mobile-menu icon-button" onClick={()=>setMobileMenu(true)}><Menu/></button><div className="mobile-logo"><Logo/></div><div className="topbar-spacer"/><span className={`sync-indicator ${syncState.status}`} title={syncState.error||'Estado da sincronização'}><i/>{syncState.status==='syncing'?'Sincronizando':syncState.status==='offline'?'Offline':syncState.status==='error'?'Erro ao sincronizar':'Sincronizado'}</span><button className="icon-button" onClick={()=>setDark(!dark)} aria-label={dark?"Ativar tema claro":"Ativar tema escuro"}>{dark?<Sun/>:<Moon/>}</button><div className="header-menu-wrap"><button className="notification icon-button" onClick={()=>{setNotificationsOpen(!notificationsOpen);setProfileOpen(false)}} aria-label="Abrir notificações"><Bell/>{unread>0&&<i>{unread}</i>}</button>{notificationsOpen&&<div className="header-popover notification-panel"><div className="notification-panel-head"><b>Notificações</b><button onClick={()=>setNotifications(n=>n.map(x=>({...x,read:true})))}><Check size={15}/> Marcar lidas</button></div><div className="notification-scroll">{notifications.length?notifications.map(n=><button className={`notification-item ${n.read?'read':''}`} key={n.id} onClick={()=>setNotifications(list=>list.map(x=>x.id===n.id?{...x,read:true}:x))}><i/><span><b>{n.title}</b><small>{n.text}</small><time>{n.time}</time></span></button>):<p className="popover-empty">Nenhuma notificação.</p>}</div></div>}</div><div className="header-menu-wrap"><button className="top-profile" onClick={()=>{setProfileOpen(!profileOpen);setNotificationsOpen(false)}}><Avatar who="R" small label={people.Rafael.name}/><span><b>{loggedName?.split(' ')[0]||people.Rafael.name.split(' ')[0]}</b></span><ChevronDown size={15}/></button>{profileOpen&&<form className="header-popover profile-popover" onSubmit={saveProfile}><h3>Editar perfil</h3><label>Nome<input value={people.Rafael.name} onChange={e=>setPeople({...people,Rafael:{...people.Rafael,name:e.target.value}})} required/></label><button className="primary">Salvar alterações</button>{user&&<button type="button" className="ghost danger" onClick={signOut}>Sair da conta</button>}</form>}</div></header><main>{content}</main></div>
    <nav className="bottom-nav">{[["Dashboard",Home],["Transações",ReceiptText],["plus",Plus],["Metas",Target],["IA Conselheira",Sparkles]].map(([label,Icon]:any)=><button key={label} className={label==='plus'?'fab':active===label?'active':''} onClick={()=>label==='plus'?setModal(true):navigate(label)}><Icon/>{label!=='plus'&&<span>{label==='IA Conselheira'?'IA':label}</span>}</button>)}</nav>
    {modal&&<TransactionModal people={people} isCouple={isCouple} close={()=>setModal(false)} success={saveTransaction}/>}{toast&&<div className="toast"><Check/> {actionToast||'Alterações salvas com sucesso!'}</div>}
    {dialog&&<div className="system-dialog-backdrop" onMouseDown={event=>event.target===event.currentTarget&&!dialog.alert&&closeDialog(false)}><section className={`system-dialog ${dialog.danger?'danger':''}`} role="dialog" aria-modal="true" aria-labelledby="system-dialog-title"><div className="system-dialog-icon">{dialog.danger?<Flag size={22}/>:<Check size={22}/>}</div><div className="system-dialog-copy"><span>JUNTOS FINANCE</span><h2 id="system-dialog-title">{dialog.title||'Confirmar ação'}</h2><p>{dialog.message}</p></div><div className="system-dialog-actions">{!dialog.alert&&<button className="ghost" onClick={()=>closeDialog(false)}>{dialog.cancelLabel||'Cancelar'}</button>}<button className={dialog.danger?'danger-button':'primary'} onClick={()=>closeDialog(true)} autoFocus>{dialog.confirmLabel||'Confirmar'}</button></div></section></div>}
  </div>
}

export default function HomePage(){return <AuthGate><FinanceApp/></AuthGate>}
